    color: #60A5FA;
  }
  .vtj-tech-load-more-btn:hover {
    background: #2563EB;
    color: #FFFFFF;
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgba(37, 99, 235, 0.25);
  }
  html.dark .vtj-tech-load-more-btn:hover {
    background: #2563EB;
    color: #FFFFFF;
    border-color: #2563EB;
  }

  /* Right: Sidebar Area */
  .vtj-tech-sidebar {
    display: flex;
    flex-direction: column;
    gap: 24px;
  }
  .vtj-stay-connected-card {
    background: #FFFFFF;
    border: 1px solid #E2E8F0;
