  }
  .vtj-sidebar-title {
    font-family: var(--font-heading);
    font-size: 1.25rem;
    font-weight: 700;
    color: #0F172A;
    margin: 0;
    letter-spacing: -0.01em;
  }
  html.dark .vtj-sidebar-title {
    color: #F8FAFC;
  }
  .vtj-social-list {
    display: flex;
    flex-direction: column;
  }
  .vtj-social-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
