  }
  .vtj-social-item-left {
    display: flex;
    align-items: center;
    gap: 12px;
  }
  .vtj-social-icon-box {
    width: 38px;
    height: 38px;
    border-radius: 9px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }
  .vtj-social-icon-whatsapp {
    background: #25D366;
    color: #FFFFFF;
  }
  .vtj-social-icon-youtube {
    background: #FF0000;
    color: #FFFFFF;
  }
  .vtj-social-icon-instagram {
    background: linear-gradient(45deg, #F09433 0%, #E6683C 25%, #DC2743 50%, #CC2366 75%, #BC1888 100%);
    color: #FFFFFF;
  }
  .vtj-social-icon-x {
    background: #000000;
    color: #FFFFFF;
  }
  .vtj-social-icon-linkedin {
    background: #0A66C2;
    color: #FFFFFF;
  }
  .vtj-social-name {
