  }
  html.dark .vtj-social-name {
    color: #F8FAFC;
  }
  .vtj-social-sub {
    font-size: 0.78rem;
    color: #64748B;
    margin: 3px 0 0;
  }
  html.dark .vtj-social-sub {
    color: #94A3B8;
  }
  .vtj-social-arrow {
    color: #94A3B8;
    transition: transform 0.2s ease, color 0.2s ease;
    display: flex;
    align-items: center;
  }
  .vtj-social-item:hover .vtj-social-arrow {
    transform: translateX(4px);
    color: #2563EB;
  }

  /* Newsletter Card */
  .vtj-newsletter-card {
    background: #FFFFFF;
    border: 1px solid #E2E8F0;
    border-radius: 14px;
    padding: 24px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  }
  html.dark .vtj-newsletter-card {
    background: #111827;
    border-color: #1E293B;
  }
  .vtj-newsletter-icon {
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: #EFF6FF;
    border: 1px solid #DBEAFE;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 1.1rem;
    color: #2563EB;
  }
  html.dark .vtj-newsletter-icon {
    background: rgba(37, 99, 235, 0.15);
    border-color: rgba(37, 99, 235, 0.3);
    color: #60A5FA;
  }
  .vtj-newsletter-title {
    font-family: var(--font-heading);
    font-size: 1.2rem;
    font-weight: 700;
    color: #0F172A;
    line-height: 1.32;
    margin: 0 0 0.55rem;
    letter-spacing: -0.01em;
  }
