    color: #94A3B8;
  }
  .vtj-newsletter-input {
    width: 100%;
    box-sizing: border-box;
    padding: 11px 14px;
    border: 1px solid #CBD5E1;
    border-radius: 8px;
    font-size: 0.88rem;
    font-family: var(--font-body);
    color: #0F172A;
    background: #FFFFFF;
    margin-bottom: 0.75rem;
