  /* Responsive Media Queries for Section 8B */
  @media (max-width: 1100px) {
    .vtj-latest-tech-grid {
      grid-template-columns: minmax(0, 1fr) 310px;
      gap: 24px;
    }
  }
  @media (max-width: 992px) {
    .vtj-latest-tech-grid {
      grid-template-columns: 1fr;
      gap: 36px;
    }
    .vtj-latest-tech-container {
      padding: 0 1.5rem;
    }
  }
  @media (max-width: 768px) {
    .vtj-latest-tech-section {
      padding: 2.25rem 0 2.75rem;
    }
    .vtj-latest-tech-container {
      padding: 0 1rem;
    }
    .vtj-tech-card {
      flex-direction: column;
      padding: 0;
      border-radius: 12px;
      overflow: hidden;
      gap: 0;
    }
    .vtj-tech-card-img-wrap {
      width: 100%;
      border-radius: 12px 12px 0 0;
      aspect-ratio: 16 / 9;
    }
    .vtj-tech-card-content {
      width: 100%;
      padding: 14px 16px 16px;
      box-sizing: border-box;
    }
    .vtj-tech-card-title {
      font-size: 1.08rem;
    }
    .vtj-tech-load-more-btn {
      width: 100%;
      box-sizing: border-box;
    }
  }

