    height: 80px !important;
  }
  .vtj-hero-card-small .vtj-hero-title-sub {
    font-size: 0.82rem !important;
  }
}

body.script:
//
  (function(){
    var FALLBACK_IMG = 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&auto=format&fit=crop&q=70';
    var FALLBACK_HERO = 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=1920&auto=format&fit=crop&q=80';

    /* ---- Utility ---- */
    function getThumb(entry, size) {
      if (entry.media$thumbnail && entry.media$thumbnail.url) {
        return entry.media$thumbnail.url
          .replace('/s72-c/', '/w' + size + '-h' + size + '-c-rw/')
          .replace(/\/s\d+(-c)?\//, '/w' + size + '-h' + size + '-c-rw/')
          .replace(/\/w\d+-h\d+(-c)?\//, '/w' + size + '-h' + size + '-c-rw/')
          .replace(/=s\d+.*$/, '=w' + size + '-h' + size + '-c-rw')
          .replace(/=w\d+-h\d+.*$/, '=w' + size + '-h' + size + '-c-rw');
      }
      return FALLBACK_IMG;
    }
    function getUrl(entry) {
      if (!entry.link) return '#';
      for (var i = 0; entry.link.length > i; i++) {
        if (entry.link[i].rel === 'alternate') return entry.link[i].href;
      }
      return '#';
    }
    function getCategory(entry) {
      if (entry.category && entry.category.length > 0) return entry.category[0].term;
      return 'Technology';
    }
    function formatDate(dateStr) {
      try {
        var d = new Date(dateStr);
        return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
      } catch(e) { return ''; }
    }
    function calcReadTime(text) {
      var words = text ? text.trim().split(/\s+/).length : 200;
      return Math.max(1, Math.round(words / 220));
    }

    /* ---- Theme Toggle ---- */
    function toggleTheme() {
      var isDark = document.documentElement.classList.toggle('dark');
      localStorage.setItem('tvh-theme', isDark ? 'dark' : 'light');
    }
    var navThemeBtn = document.getElementById('nav-theme-btn');
    if (navThemeBtn) navThemeBtn.addEventListener('click', toggleTheme);

    /* ---- Enhanced Live Search with Instant Matching & Recommendations ---- */
    (function () {
      var overlay = document.getElementById('search-overlay');
      var overlayClose = document.getElementById('search-overlay-close');
      var overlayInput = document.getElementById('search-overlay-input');
      var resultsContainer = document.getElementById('search-overlay-results');
      var quickTags = document.getElementById('search-quick-tags');
      var navSearchBtn = document.getElementById('nav-search-btn');

      var searchIndex = [];
      var searchIndexMap = {};

      // Helper to add article to search index
      function addToIndex(item, isFromFeed) {
        if (!item || !item.url || !item.title) return;
        var cleanUrl = item.url.split('?')[0].split('#')[0];
        if (searchIndexMap[cleanUrl]) {
          if (isFromFeed) {
            // Authoritative update from live Blogger Feed
            for (var i = 0; i < searchIndex.length; i++) {
              if (searchIndex[i].url.split('?')[0].split('#')[0] === cleanUrl) {
                if (item.thumb) searchIndex[i].thumb = item.thumb;
                if (item.title) searchIndex[i].title = item.title.trim();
                if (item.desc) searchIndex[i].desc = item.desc.trim();
                if (item.label) searchIndex[i].label = item.label;
                break;
              }
            }
          }
          return;
        }
        searchIndexMap[cleanUrl] = true;
        searchIndex.push({
          title: item.title.trim(),
          url: item.url,
          thumb: item.thumb || '',
          label: item.label || 'Technology',
          desc: item.desc ? item.desc.trim() : ''
        });
      }

      // Index all articles already rendered on the page immediately
      function indexPageArticles() {
        var selectors = [
          '.vtj-hero-card',
          '.vtj-article-card',
          '.vtj-tech-card',
          '.vtj-ai-featured',
          '.vtj-ai-secondary-card',
          '.vtj-coding-card',
          '.vtj-devtool-card',
          '.vtj-mustread-featured',
          '.vtj-mustread-compact-card',
          '.vtj-popular-item'
        ];

        selectors.forEach(function (sel) {
          document.querySelectorAll(sel).forEach(function (card) {
            var link = card.querySelector('a') || (card.tagName === 'A' ? card : null);
            var titleEl = card.querySelector('h1, h2, h3, .post-title, .vtj-card-title, .vtj-tech-card-title, .vtj-ai-featured-title, .vtj-ai-secondary-title, .vtj-coding-card-title, .vtj-devtool-title, .vtj-mustread-featured-title, .vtj-mustread-compact-title, .vtj-popular-title');
            var imgEl = card.querySelector('img');
            var badgeEl = card.querySelector('.vtj-hero-badge, .vtj-card-badge-overlay, .vtj-tech-badge, .vtj-cat-badge, .vtj-devtool-badge, .vtj-mustread-featured-badge, .vtj-editors-badge');
            var descEl = card.querySelector('p, .vtj-hero-desc, .vtj-card-desc, .vtj-tech-card-excerpt, .vtj-ai-featured-desc, .vtj-coding-card-desc, .vtj-devtool-excerpt, .vtj-mustread-featured-desc');

            if (link && titleEl) {
              addToIndex({
                title: titleEl.textContent || '',
                url: link.href || '',
                thumb: imgEl ? (imgEl.getAttribute('src') || '') : '',
                label: badgeEl ? badgeEl.textContent.trim() : 'Technology',
                desc: descEl ? descEl.textContent.trim() : ''
              }, false);
            }
          });
        });
      }

      // Multi-batch full blog post indexing (fetches ALL posts dynamically across batches)
      var totalSearchPostsCount = 50;
      var searchPostsLoaded = 0;

      function fetchSearchFeedBatch(startIndex) {
        var cbName = 'vtjSearchBatch_' + startIndex;
        window[cbName] = function (data) {
          try { delete window[cbName]; } catch (e) {}

          var feed = data && data.feed ? data.feed : {};
          if (feed.openSearch$totalResults && feed.openSearch$totalResults.$t) {
            var tr = parseInt(feed.openSearch$totalResults.$t, 10);
            if (!isNaN(tr) && tr > 0) totalSearchPostsCount = tr;
          }

          var entries = feed.entry || [];
          searchPostsLoaded += entries.length;

          entries.forEach(function (entry) {
            var title = entry.title ? entry.title.$t : '';
            var summary = entry.summary ? entry.summary.$t : (entry.content ? entry.content.$t : '');
            var text = summary.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
            var label = (entry.category && entry.category.length) ? entry.category[0].term : 'Article';
            var url = '';
            if (entry.link) {
              for (var i = 0; i < entry.link.length; i++) {
                if (entry.link[i].rel === 'alternate') {
                  url = entry.link[i].href;
                  break;
                }
              }
            }
            var thumb = '';
            if (typeof getFirstImgSrc === 'function') {
              thumb = getFirstImgSrc(entry);
            } else if (entry.media$thumbnail && entry.media$thumbnail.url) {
              thumb = entry.media$thumbnail.url
                .replace(/\/s\d+(-c)?\//, '/w400-h240-c-rw/')
                .replace(/=s\d+.*$/, '=w400-h240-c-rw');
            } else if (entry.content && entry.content.$t) {
              var cm = entry.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
              if (cm && cm[1]) thumb = cm[1];
            } else if (entry.summary && entry.summary.$t) {
              var sm = entry.summary.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
              if (sm && sm[1]) thumb = sm[1];
            }

            addToIndex({
              title: title,
              url: url,
              thumb: thumb,
              label: label,
              desc: text.slice(0, 160)
            }, true);
          });

          // Refresh live search results if user is currently searching
          if (overlay && overlay.classList.contains('active') && overlayInput && overlayInput.value.trim().length >= 2) {
            performLiveSearch();
          }

          // Auto-fetch next batch until ALL posts in the blog are indexed!
          if (entries.length > 0 && searchPostsLoaded < totalSearchPostsCount) {
            var nextIndex = searchPostsLoaded + 1;
            fetchSearchFeedBatch(nextIndex);
          }
        };

        var s = document.createElement('script');
        s.src = (window.location.origin || '') + '/feeds/posts/summary?alt=json-in-script&start-index=' + startIndex + '&max-results=50&callback=' + cbName;
        document.head.appendChild(s);
      }

      function loadBloggerFeed() {
        if (window.__vtjFeedLoaded) return;
        window.__vtjFeedLoaded = true;
        fetchSearchFeedBatch(1);
      }

      function openSearch() {
        if (overlay) {
          overlay.classList.add('active');
          document.body.style.overflow = 'hidden';
          indexPageArticles();
          loadBloggerFeed();
          setTimeout(function () {
            if (overlayInput) overlayInput.focus();
          }, 100);
        }
      }

      function closeSearch() {
        if (overlay) {
          overlay.classList.remove('active');
          document.body.style.overflow = '';
          if (overlayInput) overlayInput.value = '';
          if (resultsContainer) resultsContainer.innerHTML = '';
        }
      }

      if (navSearchBtn) {
        navSearchBtn.addEventListener('click', function (e) {
          e.preventDefault();
          openSearch();
        });
      }
      if (overlayClose) {
        overlayClose.addEventListener('click', closeSearch);
      }
      if (overlay) {
        overlay.addEventListener('click', function (e) {
          if (e.target === overlay) closeSearch();
        });
      }
      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') closeSearch();
      });

      // Highlight matching words helper
      function highlight(text, words) {
        if (!text || !words || !words.length) return text || '';
        var escaped = words.map(function (w) {
          return w.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
        }).join('|');
        var regex = new RegExp('(' + escaped + ')', 'gi');
        return text.replace(regex, '<mark>$1</mark>');
      }

      // Live search filter execution
      var debounceTimer = null;
      function performLiveSearch() {
        if (!overlayInput || !resultsContainer) return;
        var q = overlayInput.value.trim().toLowerCase();

        if (q.length < 2) {
          resultsContainer.innerHTML = '';
          if (quickTags) quickTags.style.display = 'flex';
          return;
        }

        if (quickTags) quickTags.style.display = 'none';

        var words = q.split(/\\s+/).filter(Boolean);
        var matches = [];

        searchIndex.forEach(function (item) {
          var titleLow = item.title.toLowerCase();
          var descLow = item.desc.toLowerCase();
          var labelLow = item.label.toLowerCase();
          var score = 0;

          // Full phrase match
          if (titleLow.indexOf(q) !== -1) score += 120;
          if (labelLow.indexOf(q) !== -1) score += 80;
          if (descLow.indexOf(q) !== -1) score += 40;

          // Word by word matching
          var allWordsFound = true;
          words.forEach(function (w) {
            var inTitle = titleLow.indexOf(w) !== -1;
            var inLabel = labelLow.indexOf(w) !== -1;
            var inDesc = descLow.indexOf(w) !== -1;

            if (inTitle) score += 30;
            if (inLabel) score += 20;
            if (inDesc) score += 10;

            if (!inTitle && !inLabel && !inDesc) {
              allWordsFound = false;
            }
          });

          if (score > 0 || allWordsFound) {
            matches.push({ item: item, score: score });
          }
        });

        // Sort by score descending
        matches.sort(function (a, b) {
          return b.score - a.score;
        });

        if (matches.length === 0) {
          resultsContainer.innerHTML = '<div class="search-no-results">' +
            '<p>No articles found matching <strong>"' + q.replace(/</g, '&lt;') + '"</strong></p>' +
            '<p style="margin-top:6px;font-size:0.8rem;color:#64748B;">Try searching for: AI, Python, Coding, Tools, Jobs, or Guides.</p>' +
            '</div>';
          return;
        }

        var html = '<div class="search-results-count">Found ' + matches.length + ' matching ' + (matches.length === 1 ? 'article' : 'articles') + '</div>';

        matches.slice(0, 10).forEach(function (m) {
          var art = m.item;
          var thumbHtml = art.thumb ? '<img class="search-result-thumb" src="' + art.thumb + '" alt="" loading="lazy"/>' : '<div class="search-result-thumb" style="display:flex;align-items:center;justify-content:center;color:#38BDF8;font-size:1.2rem;">&#9889;</div>';
          html += '<a class="search-result-item" href="' + art.url + '">' +
            thumbHtml +
            '<div class="search-result-info">' +
              '<span class="search-result-badge">' + highlight(art.label, words) + '</span>' +
              '<h4 class="search-result-title">' + highlight(art.title, words) + '</h4>' +
              (art.desc ? '<p class="search-result-desc">' + highlight(art.desc, words) + '</p>' : '') +
            '</div>' +
          '</a>';
        });

        resultsContainer.innerHTML = html;
      }

      if (overlayInput) {
        overlayInput.addEventListener('input', function () {
          clearTimeout(debounceTimer);
          debounceTimer = setTimeout(performLiveSearch, 100);
        });
      }

      // Quick Tags click handler
      document.querySelectorAll('.quick-tag-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
          if (overlayInput) {
            overlayInput.value = btn.textContent.trim();
            performLiveSearch();
          }
        });
      });

      // Init on load
      indexPageArticles();
      setTimeout(loadBloggerFeed, 1000);
    })();

    /* ---- Mobile Drawer ---- */
    var drawer = document.getElementById('mobile-drawer');
    var drawerOverlay = document.getElementById('drawer-overlay');
    var drawerClose = document.getElementById('drawer-close');
    var hamburger = document.getElementById('nav-hamburger');
    function openDrawer() { if (drawer) drawer.classList.add('active'); if (drawerOverlay) drawerOverlay.classList.add('active'); }
    function closeDrawer() { if (drawer) drawer.classList.remove('active'); if (drawerOverlay) drawerOverlay.classList.remove('active'); }
    if (hamburger) hamburger.addEventListener('click', openDrawer);
    if (drawerClose) drawerClose.addEventListener('click', closeDrawer);
    if (drawerOverlay) drawerOverlay.addEventListener('click', closeDrawer);

    /* ---- Sticky Header Scroll ---- */
    var siteHeader = document.getElementById('site-header');
    window.addEventListener('scroll', function() {
      if (!siteHeader) return;
      if (100 > window.scrollY) { siteHeader.classList.remove('scrolled'); }
      else { siteHeader.classList.add('scrolled'); }
    }, { passive: true });

    /* ====================================================
       AUTOMATIC DYNAMIC BLOGGER PROFILE LOGO SYNCHRONIZATION
       Whenever you change your profile image in Blogger, it
       automatically updates across the entire website.
    ==================================================== */
    var VTJ_DEFAULT_LOGO = 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEge9Td0E3H4yHTPNowC7tK97amSK1BNQL2HGnDb5qX_kTLpdobP6lV2xOsS-vu2yIubYFH6MDMe5oKLfKNdK_fc3G1eOrml03rD1MPH8f6bB9gfK9f8A6UNtr9zqiwVgyPYv4XhKtitj43HscUphwGzPzLqNaAhir-ATrqBhi7_ptIUS98/s1600/profile_image.png';

    function getHighResProfileImg(url) {
      if (!url) return '';
      return url
        .replace(/\/s\d+(-c)?\//, '/s1600/')
        .replace(/\/w\d+-h\d+(-c)?\//, '/s1600/')
        .replace(/=s\d+.*$/, '=s1600')
        .replace(/=w\d+-h\d+.*$/, '=s1600');
    }

    function applyLogoToAllElements(src) {
      if (!src) return;
      var h = document.getElementById('header-logo-img');
      if (h && h.src !== src) { h.src = src; h.style.display = ''; }

      var d = document.getElementById('drawer-logo-img');
      if (d && d.src !== src) { d.src = src; d.style.display = 'block'; }

      var f = document.getElementById('footer-logo-img');
      if (f && f.src !== src) { f.src = src; f.style.display = 'block'; }

      var heroAvatars = document.querySelectorAll('.vtj-hero-author-avatar');
      for (var i = 0; i < heroAvatars.length; i++) {
        if (heroAvatars[i].src !== src) heroAvatars[i].src = src;
      }

      var spotAvatar = document.getElementById('vtj-spotlight-author-img');
      if (spotAvatar && spotAvatar.src !== src) { spotAvatar.src = src; }

      var postAvatar = document.getElementById('post-author-avatar-img');
      if (postAvatar && postAvatar.src !== src) { postAvatar.src = src; postAvatar.style.display = ''; }
      var bioAvatar = document.getElementById('author-bio-avatar-img');
      if (bioAvatar && bioAvatar.src !== src) { bioAvatar.src = src; bioAvatar.style.display = ''; }
      var postColAvatars = document.querySelectorAll('.vtj-post-author-avatar img');
      for (var k = 0; k < postColAvatars.length; k++) {
        if (postColAvatars[k].src !== src) postColAvatars[k].src = src;
      }

      var ab = document.getElementById('about-sidebar-logo');
      if (ab) {
        var existingAb = ab.querySelector('img');
        if (existingAb) {
          if (existingAb.src !== src) existingAb.src = src;
        } else {
          var aimg = document.createElement('img');
          aimg.src = src;
          aimg.alt = 'Vicky Tech Journal';
          aimg.width = 120;
          aimg.height = 120;
          aimg.loading = 'lazy';
          ab.appendChild(aimg);
        }
      }

      var ytAv = document.getElementById('social-avatar-yt');
      if (ytAv) {
        var existingYt = ytAv.querySelector('img');
        if (existingYt) { if (existingYt.src !== src) existingYt.src = src; }
        else {
          var ytImg = document.createElement('img');
          ytImg.src = src;
          ytImg.alt = 'Vicky Tech Journal';
          ytImg.width = 72;
          ytImg.height = 72;
          ytImg.loading = 'lazy';
          ytAv.appendChild(ytImg);
        }
      }

      var igAv = document.getElementById('social-avatar-ig');
      if (igAv) {
        var existingIg = igAv.querySelector('img');
        if (existingIg) { if (existingIg.src !== src) existingIg.src = src; }
        else {
          var igImg = document.createElement('img');
          igImg.src = src;
          igImg.alt = 'Vicky Tech Journal';
          igImg.width = 72;
          igImg.height = 72;
          igImg.loading = 'lazy';
          igAv.appendChild(igImg);
        }
      }

      try {
        var favicons = document.querySelectorAll("link[rel*='icon']");
        for (var fv = 0; fv < favicons.length; fv++) {
          favicons[fv].href = src;
        }
      } catch(e) {}
    }

    function initDynamicProfileSync() {
      // 1. Immediately apply cached logo if available (0ms instant render)
      var activeLogo = VTJ_DEFAULT_LOGO;
      try {
        var cached = localStorage.getItem('vtj_current_profile_logo');
        if (cached) activeLogo = cached;
      } catch(e) {}
      applyLogoToAllElements(activeLogo);

      // 2. Fetch Blogger feed to detect any live profile image updates
      window.vtjLiveProfileCb = function(data) {
        var liveImg = '';
        try {
          if (data && data.feed) {
            if (data.feed.author && data.feed.author[0] && data.feed.author[0].gd$image) {
              liveImg = data.feed.author[0].gd$image.src || '';
            }
            if (!liveImg && data.feed.entry && data.feed.entry[0] && data.feed.entry[0].author && data.feed.entry[0].author[0] && data.feed.entry[0].author[0].gd$image) {
              liveImg = data.feed.entry[0].author[0].gd$image.src || '';
            }
          }
        } catch(e) {}

        if (liveImg) {
          var hiResLive = getHighResProfileImg(liveImg);
          try {
            localStorage.setItem('vtj_current_profile_logo', hiResLive);
          } catch(e) {}
          applyLogoToAllElements(hiResLive);
        }
      };

      var BLOG_FEED_BASE = document.body.getAttribute('data-url') || '/';
      if (BLOG_FEED_BASE.charAt(BLOG_FEED_BASE.length - 1) !== '/') BLOG_FEED_BASE += '/';

      var s = document.createElement('script');
      s.src = BLOG_FEED_BASE + 'feeds/posts/summary?alt=json-in-script&max-results=1&callback=vtjLiveProfileCb';
      document.body.appendChild(s);
    }

    initDynamicProfileSync();

    /* ---- Subscribe Dropdown ---- */
    (function(){
      var btn = document.getElementById('nav-subscribe-btn');
      var dd  = document.getElementById('nav-subscribe-dropdown');
      if (!btn || !dd) return;
      btn.addEventListener('click', function(e){
        e.stopPropagation();
        dd.classList.toggle('open');
      });
      document.addEventListener('click', function(e){
        if (!dd.contains(e.target) && !btn.contains(e.target)) {
          dd.classList.remove('open');
        }
      });
    })();

    /* ---- Fade-in on Scroll ---- */
    if ('IntersectionObserver' in window) {
      var io = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
          if (entry.isIntersecting) { entry.target.classList.add('visible'); io.unobserve(entry.target); }
        });
      }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });
      document.querySelectorAll('.fade-in-ready').forEach(function(el) { io.observe(el); });
    } else {
      document.querySelectorAll('.fade-in-ready').forEach(function(el) { el.classList.add('visible'); });
    }

    /* ---- Reading Time (card estimates) ---- */
    document.querySelectorAll('.post-read-time-val').forEach(function(el) {
      var card = el.closest('.post-card');
      if (!card) return;
      var excerpt = card.querySelector('.post-card-excerpt');
      if (excerpt) {
        var words = excerpt.textContent.trim().split(/\s+/).length * 8;
        el.textContent = Math.max(2, Math.round(words / 220)) + ' min';
      }
    });

    /* ====================================================
       HOMEPAGE-ONLY DYNAMIC CONTENT
    ==================================================== */
    var isHomepage = document.getElementById("vtj-featured-slider-section") !== null;
    var BLOG_URL = document.body.getAttribute("data-url") || "";
    if (!BLOG_URL || BLOG_URL.indexOf("blogger.com") !== -1) {
      BLOG_URL = "/";
    } else if (BLOG_URL.charAt(BLOG_URL.length - 1) !== "/") {
      BLOG_URL += "/";
    }

    function isArticlesRoute() {
      var p = window.location.pathname.toLowerCase();
      var s = window.location.search.toLowerCase();
      var h = window.location.hash.toLowerCase();
      return p.indexOf('/p/articles') !== -1 || p === '/articles' || s.indexOf('view=articles') !== -1 || s.indexOf('page=articles') !== -1 || h === '#articles';
    }

    if (isArticlesRoute()) {
      loadArticlesPage();
      return;
    }

    if (!isHomepage) {
      initSinglePost();
      return;
    }

    /* ---- High-Resolution Image Helper ---- */
    function getFirstImgSrc(entry) {
      var content = (entry.content && entry.content.$t) || '';
      if (content) {
        var cm = content.match(/<img[^>]+src=["']([^"']+)["']/i);
        if (cm && cm[1] && cm[1].indexOf('data:') !== 0) {
          return cm[1]
            .replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/')
            .replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/')
            .replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/')
            .replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw')
            .replace(/=s\d+.*$/, '=w800-h450-c-rw');
        }
      }
      if (entry.media$thumbnail && entry.media$thumbnail.url) {
        return entry.media$thumbnail.url
          .replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/')
          .replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/')
          .replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/')
          .replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw')
          .replace(/=s\d+.*$/, '=w800-h450-c-rw');
      }
      var summary = (entry.summary && entry.summary.$t) || '';
      if (summary) {
        var sm = summary.match(/<img[^>]+src=["']([^"']+)["']/i);
        if (sm && sm[1]) return sm[1];
      }
      return FALLBACK_IMG;
    }

    function cleanSummary(text, length) {
      if (!text) return '';
      var temp = document.createElement('div');
      temp.innerHTML = text;
      var clean = temp.textContent || temp.innerText || '';
      clean = clean.replace(/\s+/g, ' ').trim();
      if (clean.length > length) {
        clean = clean.substring(0, length).trim() + '...';
      }
      return clean;
    }

    function getReadingTime(entry) {
      var text = (entry.content && entry.content.$t) || (entry.summary && entry.summary.$t) || '';
      var cleanText = text.replace(/<[^>]*>/g, '').trim();
      var words = cleanText.split(/\s+/).length;
      if (entry.content) {
        return Math.max(1, Math.round(words / 220));
      } else {
        return Math.max(2, Math.round((words * 8) / 220));
      }
    }

    /* ---- Featured Post Slider ---- */
    var sliderEntries = [];
    var sliderCurrent = 0;
    var sliderTimer = null;
    var sliderInterval = 4000;
    var sliderIsPaused = false;
    var DEFAULT_FEATURED_IMAGE = "https://images.unsplash.com/photo-1677442136019-21780efad99a?w=800&auto=format&fit=crop&q=80";

    function escapeHtml(str) {
      return (str || '')
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
    }

    function getHighQualityImage(url) {
      if (!url) return DEFAULT_FEATURED_IMAGE;

      return url
        .replace(/\/s72-c\//, "/w800-h450-c-rw/")
        .replace(/\/s100-c\//, "/w800-h450-c-rw/")
        .replace(/\/s150-c\//, "/w800-h450-c-rw/")
        .replace(/\/s[0-9]+(-c)?\//, "/w800-h450-c-rw/")
        .replace(/=s[0-9]+(-c)?/, "=w800-h450-c-rw")
        .replace(/\/w[0-9]+-h[0-9]+(-c)?\//, "/w800-h450-c-rw/")
        .replace(/\/w[0-9]+-h[0-9]+-p-k-no-nu\//, "/w800-h450-c-rw/");
    }

    function loadHeroSlider() {
      if (!document.getElementById("vtj-featured-slider-container")) return;
      var s = document.createElement("script");
      s.src = BLOG_URL + "feeds/posts/summary?alt=json-in-script&max-results=10&callback=vtjHeroSliderCb";
      document.body.appendChild(s);
      setTimeout(function() {
        if (sliderEntries.length === 0) renderHeroSliderFallback();
      }, 5000);
    }

    window.vtjHeroSliderCb = function(data) {
      var entries = data.feed && data.feed.entry ? data.feed.entry : [];
      if (entries.length === 0) { renderHeroSliderFallback(); return; }
      sliderEntries = entries;
      renderHeroSlider(entries);
    };

    function renderHeroSliderFallback() {
      var mockups = [
        { title: "Top 10 AI Tools to Boost Your Daily Productivity", cat: "AI Tools", img: "https://images.unsplash.com/photo-1677442136019-21780efad99a?w=800&auto=format&fit=crop&q=80", summary: "Discover the best artificial intelligence tools that can help automate your workflow, write code faster, and design premium assets.", date: "Jul 20, 2026", rt: 5 },
        { title: "Essential Software Guides Every Student Should Read", cat: "Software", img: "https://images.unsplash.com/photo-1501504905252-473c47e087f8?w=800&auto=format&fit=crop&q=80", summary: "Learn about the most useful open source software, desktop apps, and coding editors for college and high school students.", date: "Jul 19, 2026", rt: 4 },
        { title: "How to Secure Your Digital Footprint Online in 2026", cat: "Cyber Security", img: "https://images.unsplash.com/photo-1563986768609-322da13575f3?w=800&auto=format&fit=crop&q=80", summary: "A comprehensive guide on online privacy, securing password managers, browser extensions, and routing traffic securely.", date: "Jul 18, 2026", rt: 6 },
        { title: "15 Chrome Extensions That Save Hours of Coding Work", cat: "Extensions", img: "https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=800&auto=format&fit=crop&q=80", summary: "A handpicked list of extensions for developer tools, color picking, CSS inspection, and console formatting.", date: "Jul 18, 2026", rt: 5 }
      ];
      var mockEntries = mockups.map(function(m) {
        return {
          title: { $t: m.title },
          summary: { $t: m.summary },
          published: { $t: new Date(m.date).toISOString() },
          category: [{ term: m.cat }],
          link: [{ rel: "alternate", href: "#" }],
          media$thumbnail: { url: m.img }
        };
      });
      sliderEntries = mockEntries;
      renderHeroSlider(mockEntries);
    }

    function renderHeroSlider(entries) {
      var container = document.getElementById("vtj-featured-slider-container");
      if (!container) return;

      var track = document.createElement("div");
      track.className = "featured-slider-track";
      track.id = "vtj-featured-slider-track";
      track.setAttribute("aria-live", "polite");

      var dotsHtml = "";
      for (var i = 0; i < entries.length; i++) {
        var slide = document.createElement("div");
        slide.className = "featured-slide" + (i === 0 ? " active" : "");
        slide.setAttribute("role", "group");
        slide.setAttribute("aria-roledescription", "slide");
        slide.setAttribute("aria-label", "Slide " + (i + 1) + " of " + entries.length);
        slide.innerHTML = buildHeroSlideHtml(entries[i], i);
        track.appendChild(slide);

        dotsHtml += "<button class='vtj-featured-slider-dot" + (i === 0 ? " active" : "") + "' data-index='" + i + "' aria-label='Go to slide " + (i + 1) + "'></button>";
      }

      container.innerHTML = "";
      container.appendChild(track);

      var dotsContainer = document.getElementById("vtj-featured-slider-dots");
      if (dotsContainer) dotsContainer.innerHTML = dotsHtml;

      initHeroSlider();
    }

    function buildHeroSlideHtml(entry, index) {
      var title = entry.title ? entry.title.$t : "";
      var safeTitle = escapeHtml(title);
      var postUrl   = getUrl(entry);
      var category   = getCategory(entry);
      var publishedDate  = formatDate(entry.published ? entry.published.$t : "");
      var description  = cleanSummary(entry.summary ? entry.summary.$t : "", 150);
      var highQualityImage   = getHighQualityImage(getFirstImgSrc(entry));
      var readingTime    = getReadingTime(entry) + " min read";
      var isFirstSlide = (index === 0);

      return "<a class='featured-image-link' href='" + postUrl + "' aria-label='Open " + safeTitle + "'>" +
        "<div class='featured-image-wrapper'>" +
          "<img class='featured-image' src='" + highQualityImage + "' alt='" + safeTitle + "' " +
          (isFirstSlide ? "loading='eager' fetchpriority='high'" : "loading='lazy' decoding='async'") +
          " width='800' height='450'/>" +
        "</div>" +
      "</a>" +
      "<div class='featured-content'>" +
        "<span class='featured-category'>" + category + "</span>" +
        "<h2 class='featured-title'><a href='" + postUrl + "'>" + safeTitle + "</a></h2>" +
        "<p class='featured-description'>" + description + "</p>" +
        "<div class='featured-meta'>" +
          "<span>" + publishedDate + "</span>" +
          "<span>" + readingTime + "</span>" +
        "</div>" +
        "<a class='featured-read-button' href='" + postUrl + "'>" +
          "Read Full Article <span aria-hidden='true'>\u2192</span>" +
        "</a>" +
      "</div>";
    }

    function initHeroSlider() {
      var prevBtn = document.getElementById("vtj-featured-slider-prev");
      var nextBtn = document.getElementById("vtj-featured-slider-next");
      var dotsContainer = document.getElementById("vtj-featured-slider-dots");
      var container = document.getElementById("vtj-featured-slider-container");
      var section = document.getElementById("vtj-featured-slider-section");

      if (prevBtn) prevBtn.addEventListener("click", function() { goToSlide(sliderCurrent - 1); });
      if (nextBtn) nextBtn.addEventListener("click", function() { goToSlide(sliderCurrent + 1); });

      if (dotsContainer) {
        dotsContainer.addEventListener("click", function(e) {
          var dot = e.target.closest(".vtj-featured-slider-dot");
          if (dot) {
            var idx = parseInt(dot.getAttribute("data-index"));
            if (!isNaN(idx)) goToSlide(idx);
          }
        });
      }

      if (container) {
        var touchStartX = 0;
        container.addEventListener("touchstart", function(e) {
          touchStartX = e.changedTouches[0].screenX;
        }, { passive: true });
        container.addEventListener("touchend", function(e) {
          var diff = touchStartX - e.changedTouches[0].screenX;
          if (Math.abs(diff) > 50) {
            goToSlide(diff > 0 ? sliderCurrent + 1 : sliderCurrent - 1);
          }
        }, { passive: true });
      }

      if (section) {
        section.addEventListener("keydown", function(e) {
          if (e.key === "ArrowLeft") { goToSlide(sliderCurrent - 1); e.preventDefault(); }
          if (e.key === "ArrowRight") { goToSlide(sliderCurrent + 1); e.preventDefault(); }
        });
      }

      if (container) {
        container.addEventListener("mouseenter", pauseSlider);
        container.addEventListener("mouseleave", resumeSlider);
      }

      if (section) {
        section.addEventListener("focusin", pauseSlider);
        section.addEventListener("focusout", function(e) {
          if (!section.contains(e.relatedTarget)) resumeSlider();
        });
      }

      document.addEventListener("visibilitychange", function() {
        if (document.hidden) pauseSlider(); else resumeSlider();
      });

      startSliderTimer();
    }

    function goToSlide(index) {
      var track = document.getElementById("vtj-featured-slider-track");
      if (!track) return;
      var slides = track.querySelectorAll(".featured-slide");
      if (slides.length === 0) return;

      if (index < 0) index = slides.length - 1;
      if (index >= slides.length) index = 0;

      slides.forEach(function(s, i) {
        var isActive = i === index;
        s.classList.toggle("active", isActive);
        s.setAttribute("aria-hidden", String(!isActive));
      });

      sliderCurrent = index;

      document.querySelectorAll(".vtj-featured-slider-dot").forEach(function(d, i) {
        d.classList.toggle("active", i === index);
      });

      resetSliderTimer();

      var nextIdx = index + 1 >= slides.length ? 0 : index + 1;
      var nextSlide = slides[nextIdx];
      if (nextSlide) {
        var nextImg = nextSlide.querySelector(".featured-image");
        if (nextImg) {
          var src = nextImg.getAttribute("src");
          if (src) { var p = new Image(); p.src = src; }
        }
      }
    }

    function startSliderTimer() {
      stopSliderTimer();
      if (sliderIsPaused) return;
      sliderTimer = setInterval(function() {
        if (!sliderIsPaused) goToSlide(sliderCurrent + 1);
      }, sliderInterval);
      startProgressBar();
    }

    function stopSliderTimer() {
      if (sliderTimer) { clearInterval(sliderTimer); sliderTimer = null; }
      stopProgressBar();
    }

    function resetSliderTimer() {
      stopSliderTimer();
      if (!sliderIsPaused) startSliderTimer();
    }

    function pauseSlider() {
      sliderIsPaused = true;
      stopSliderTimer();
    }

    function resumeSlider() {
      sliderIsPaused = false;
      startSliderTimer();
    }

    function startProgressBar() {
      var bar = document.getElementById("vtj-featured-slider-progress-bar");
      if (!bar) return;
      bar.style.transition = "none";
      bar.style.width = "0%";
      bar.offsetHeight;
      bar.style.transition = "width " + sliderInterval + "ms linear";
      bar.style.width = "100%";
    }

    function stopProgressBar() {
      var bar = document.getElementById("vtj-featured-slider-progress-bar");
      if (!bar) return;
      bar.style.transition = "none";
      bar.style.width = "0%";
    }

    /* ---- Magazine Category Blocks ---- */
    var magazineCats = [
      { label: "AI Tools",          elId: "mag-ai-tools",       blockId: "mag-block-ai-tools" },
      { label: "Useful Websites",   elId: "mag-useful-websites", blockId: "mag-block-websites" },
      { label: "Apps",              elId: "mag-apps",            blockId: "mag-block-apps" },
      { label: "Software",          elId: "mag-software",        blockId: "mag-block-software" },
      { label: "Student Tech",      elId: "mag-student-tech",    blockId: "mag-block-student" },
      { label: "Productivity",      elId: "mag-productivity",    blockId: "mag-block-productivity" }
    ];

    function makeMagCallback(cat) {
      return function(data) {
        var blockEl = document.getElementById(cat.blockId);
        var innerEl = document.getElementById(cat.elId);
        if (!innerEl) return;
        if (!data.feed || !data.feed.entry || data.feed.entry.length === 0) {
          if (blockEl) blockEl.style.display = "none";
          return;
        }
        var entries = data.feed.entry;
        var large = entries[0];
        var smalls = [];
        for (var i = 1; 4 > i && entries.length > i; i++) smalls.push(entries[i]);

        var lt = large.title ? large.title.$t : "";
        var lu = getUrl(large);
        var lc = getCategory(large);
        var ld = formatDate(large.published ? large.published.$t : "");
        var limg = getThumb(large, 600);
        var lexcerpt = large.summary ? large.summary.$t.substring(0, 120) + "..." : "";

        var html = "<div class='mag-large-card'>" +
          "<div class='mag-large-img'><a href='" + lu + "'><img src='" + limg + "' alt='" + lt.replace(/\"/g, "'") + "' width='600' height='338' loading='lazy' decoding='async'/></a>" +
          "<span class='mag-large-badge'>" + lc + "</span></div>" +
          "<div class='mag-large-body'>" +
          "<span class='mag-large-cat'>" + lc + "</span>" +
          "<h3 class='mag-large-title'><a href='" + lu + "'>" + lt + "</a></h3>" +
          "<p class='mag-large-excerpt'>" + lexcerpt + "</p>" +
          "<div class='mag-large-meta'><span>" + ld + "</span><span class='mag-large-meta-dot'>·</span><span>" + calcReadTime(lexcerpt) + " min read</span></div>" +
          "</div></div>";

        var smallHtml = "<div class='mag-small-group'>";
        for (var j = 0; smalls.length > j; j++) {
          var s = smalls[j];
          var st = s.title ? s.title.$t : "";
          var su = getUrl(s);
          var sc = getCategory(s);
          var sd = formatDate(s.published ? s.published.$t : "");
          var simg = getThumb(s, 200);
          smallHtml += "<div class='mag-small-card'>" +
            "<div class='mag-small-img'><a href='" + su + "'><img src='" + simg + "' alt='" + st.replace(/\"/g, "'") + "' width='200' height='150' loading='lazy' decoding='async'/></a></div>" +
            "<div class='mag-small-body'><span class='mag-small-cat'>" + sc + "</span>" +
            "<p class='mag-small-title'><a href='" + su + "'>" + st + "</a></p>" +
            "<span class='mag-small-date'>" + sd + "</span></div></div>";
        }
        smallHtml += "</div>";

        innerEl.innerHTML = html + smallHtml;
      };
    }

    function loadMagazineBlocks() {
      var firstMag = document.querySelector('.mag-block, [id^="mag-block-"], .trending-section');
      var loaded = false;
      function fetchAll() {
        if (loaded) return;
        loaded = true;
        magazineCats.forEach(function(cat, idx) {
          var cbName = "tvhMag_" + cat.elId.replace(/-/g, "_");
          window[cbName] = makeMagCallback(cat);
          setTimeout(function(c, n) {
            return function() {
              var sc = document.createElement("script");
              sc.src = BLOG_URL + "feeds/posts/summary/-/ " + encodeURIComponent(c.label) + "?alt=json-in-script&max-results=4&callback=" + n;
              document.body.appendChild(sc);
            };
          }(cat, cbName), idx * 120);

          setTimeout(function() {
            var innerEl = document.getElementById(cat.elId);
            if (innerEl && innerEl.querySelector(".skel, .mag-skel")) {
              var blockEl = document.getElementById(cat.blockId);
              if (blockEl) blockEl.style.display = "none";
            }
          }, 5000);
        });
      }

      if (firstMag && 'IntersectionObserver' in window) {
        var obs = new IntersectionObserver(function(entries, observer) {
          entries.forEach(function(entry) {
            if (entry.isIntersecting) {
              observer.disconnect();
              fetchAll();
            }
          });
        }, { rootMargin: '400px' });
        obs.observe(firstMag);
      } else {
        if ('requestIdleCallback' in window) {
          requestIdleCallback(fetchAll, { timeout: 3000 });
        } else {
          setTimeout(fetchAll, 1500);
        }
      }
    }

    /* ---- Numbered Pagination ---- */
    function buildPagination() {
      var pag = document.getElementById('vtj-pagination');
      if (!pag) return;
      if (!document.querySelector('.main-posts-area, .Blog, #Blog1')) return;
      var perPage = 8;
      var homeUrl = pag.getAttribute('data-home') || '/';
      if (homeUrl.indexOf('http') !== 0) homeUrl = window.location.protocol + '//' + window.location.host + homeUrl;
      window.vtjPagBuild = function(data) {
        var total = parseInt(data.feed.openSearch$totalResults.$t) || 0;
        var totalPages = Math.ceil(total / perPage);
        if (totalPages <= 1) { pag.innerHTML = ''; return; }
        var entries = data.feed.entry || [];
        var currentPage = 1;
        var url = window.location.href;
        var urlTs = null;
        var m = url.match(/updated-max=([^&]+)/);
        if (m) {
          urlTs = decodeURIComponent(m[1]).replace(/\+/g, ' ');
          for (var i = 0; i < entries.length; i++) {
            if (entries[i].published && entries[i].published.$t >= urlTs) {
              currentPage = Math.floor(i / perPage) + 2;
              break;
            }
          }
          if (currentPage > totalPages) currentPage = totalPages;
        }
        function pageUrl(pageNum) {
          if (pageNum <= 1) return homeUrl;
          var idx = (pageNum - 1) * perPage - 1;
          if (entries[idx] && entries[idx].published) {
            var ts = entries[idx].published.$t.replace(/\.\d+/, '').replace(/Z/, '');
            return '/search?updated-max=' + encodeURIComponent(ts) + '&max-results=' + perPage;
          }
          return null;
        }
        var win = 2;
        var startPage = Math.max(1, currentPage - win);
        var endPage = Math.min(totalPages, currentPage + win);
        if (currentPage - win < 1) endPage = Math.min(totalPages, endPage + (win - (currentPage - startPage)));
        if (currentPage + win > totalPages) startPage = Math.max(1, startPage - (win - (endPage - currentPage)));
        var html = '<nav aria-label="Pagination" class="pagination">';
        if (currentPage > 1) {
          var pu = pageUrl(currentPage - 1);
          html += '<a class="pagination-btn pagination-prev" href="' + (pu || homeUrl) + '">\u2190 Previous</a>';
        } else {
          html += '<span class="pagination-btn pagination-prev pagination-disabled">\u2190 Previous</span>';
        }
        if (startPage > 1) {
          html += '<a class="pagination-btn pagination-num" href="' + homeUrl + '">1</a>';
          if (startPage > 2) html += '<span class="pagination-ellipsis">\u2026</span>';
        }
        for (var p = startPage; p <= endPage; p++) {
          if (p === currentPage) {
            html += '<span class="pagination-btn pagination-num pagination-active">' + p + '</span>';
          } else {
            var pu = p === 1 ? homeUrl : pageUrl(p);
            if (pu) html += '<a class="pagination-btn pagination-num" href="' + pu + '">' + p + '</a>';
          }
        }
        if (endPage < totalPages) {
          if (endPage < totalPages - 1) html += '<span class="pagination-ellipsis">\u2026</span>';
          var pu = pageUrl(totalPages);
          if (pu) html += '<a class="pagination-btn pagination-num" href="' + pu + '">' + totalPages + '</a>';
        }
        if (currentPage < totalPages) {
          var pu = pageUrl(currentPage + 1);
          html += '<a class="pagination-btn pagination-next" href="' + (pu || homeUrl) + '">Next \u2192</a>';
        } else {
          html += '<span class="pagination-btn pagination-next pagination-disabled">Next \u2192</span>';
        }
        html += '</nav>';
        pag.innerHTML = html;
      };
      var s = document.createElement("script");
      s.src = BLOG_URL + "feeds/posts/summary?alt=json-in-script&max-results=150&fields=entry(published),openSearch$totalResults&callback=vtjPagBuild";
      document.body.appendChild(s);
    }

    /* ---- Latest Articles (fetch exactly 10 posts via JSON feed) ---- */
    function loadLatestArticles() {
      var grid = document.querySelector('.content-area .posts-grid');
      if (!grid) return;
      // Configuration: exactly 10 posts
      var POST_COUNT = 10;
      function imgSrcset(url) {
        var s1 = url.replace(/\/s\d+(-c)?\//, '/w400-h225-c-rw/').replace(/\/w\d+-h\d+(-c)?\//, '/w400-h225-c-rw/').replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w400-h225-c-rw/').replace(/=s\d+.*$/, '=w400-h225-c-rw').replace(/=w\d+-h\d+.*$/, '=w400-h225-c-rw');
        var s2 = url.replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/').replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/').replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/').replace(/=s\d+.*$/, '=w800-h450-c-rw').replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw');
        return s1 + ' 400w, ' + s2 + ' 800w';
      }
      window.vtjLatestCb = function(data) {
        var entries = data.feed && data.feed.entry;
        if (!entries || entries.length === 0) return;
        var html = '';
        // Process exactly POST_COUNT posts (not all available)
        var maxPosts = Math.min(entries.length, POST_COUNT);
        for (var i = 0; i < maxPosts; i++) {
          var e = entries[i];
          var rawT = e.title ? e.title.$t : '';
          var safeT = escapeHtml(rawT);
          var u = getUrl(e);
          var d = formatDate(e.published ? e.published.$t : '');
          var c = getCategory(e);
          var img = getFirstImgSrc(e);
          var snippet = e.summary ? cleanSummary(e.summary.$t, 120) : '';
          var readTime = calcReadTime(snippet || rawT);
          var loadingAttr = i === 0 ? 'eager' : 'lazy';
          var srcsetAttr = imgSrcset(img);
          html += '<article class="post-card fade-in-ready">' +
            '<div class="post-card-thumb">' +
              '<a href="' + u + '" aria-label="Read ' + safeT + '">' +
                '<img src="' + img + '" alt="' + safeT + '" loading="' + loadingAttr + '" decoding="async" width="400" height="225" srcset="' + srcsetAttr + '" sizes="(max-width: 640px) 400px, (max-width: 1024px) 50vw, 400px"/>' +
              '</a>' +
              '<span class="post-card-category">' + c + '</span>' +
            '</div>' +
            '<div class="post-card-body">' +
              '<h3 class="post-card-title"><a href="' + u + '">' + safeT + '</a></h3>' +
              '<p class="post-card-excerpt">' + snippet + '</p>' +
              '<div class="post-card-footer">' +
                '<div class="post-card-meta">' +
                  '<svg viewBox="0 0 24 24"><path d="M9 11H7v2h2v-2zm4 0h-2v2h2v-2zm4 0h-2v2h2v-2zm2-7h-1V2h-2v2H8V2H6v2H5c-1.11 0-1.99.9-1.99 2L3 20a2 2 0 002 2h14c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 16H5V9h14v11z"/></svg>' +
                  d +
                  '<span class="post-card-meta-dot"/>' +
                  '<svg viewBox="0 0 24 24"><path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm.5-13H11v6l5.25 3.15.75-1.23-4.5-2.67z"/></svg>' +
                  '<span class="post-read-time-val">' + readTime + ' min</span>' +
                '</div>' +
                '<a class="post-card-readmore" href="' + u + '">' +
                  'Read' +
                  '<svg viewBox="0 0 24 24"><path d="M12 4l-1.41 1.41L16.17 11H4v2h12.17l-5.58 5.59L12 20l8-8z"/></svg>' +
                '</a>' +
              '</div>' +
            '</div>' +
          '</article>';
        }
        grid.innerHTML = html;
        var newCards = grid.querySelectorAll('.fade-in-ready');
        if ('IntersectionObserver' in window) {
          var io2 = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
              if (entry.isIntersecting) {
                entry.target.classList.add('visible');
                io2.unobserve(entry.target);
              }
            });
          }, { threshold: 0.1 });
          newCards.forEach(function(el) { io2.observe(el); });
        } else {
          newCards.forEach(function(el) { el.classList.add('visible'); });
        }
      };
      var s = document.createElement("script");
      s.src = BLOG_URL + "feeds/posts/summary?alt=json-in-script&max-results=" + POST_COUNT + "&callback=vtjLatestCb";
      document.body.appendChild(s);
    }

    /* ---- Init All ---- */
    loadHeroSlider();
    loadLatestArticles();
    buildPagination();

    /* ============================================================
       PREMIUM ARTICLES ARCHIVE & KNOWLEDGE HUB LOGIC
    ============================================================ */
    function loadArticlesPage() {
      document.body.classList.add('articles-view');

      // Highlight Articles nav link
      try {
        var navLinks = document.querySelectorAll('.nav-menu-link, .drawer-nav-link');
        for (var n = 0; n < navLinks.length; n++) {
          var href = navLinks[n].getAttribute('href') || '';
          if (href.indexOf('/p/articles') !== -1) {
            navLinks[n].classList.add('active');
          } else if (href === '/' || href.indexOf('label') !== -1) {
            navLinks[n].classList.remove('active');
          }
        }
      } catch(e) {}

      var wrap = document.getElementById('articles-page-wrap');
      if (!wrap) return;
      wrap.style.display = 'block';

      // Hide default post/page content and sidebar
      var blog = document.querySelector('.main-posts-area, .Blog, #Blog1, #hero-bg-section');
      if (blog) blog.style.display = 'none';

      // Use header logo for avatar if available
      var logoImg = document.getElementById('header-logo-img');
      var spotAvatar = document.getElementById('vtj-spotlight-author-img');
      if (logoImg && spotAvatar && logoImg.src) {
        spotAvatar.src = logoImg.src;
      }

      const CATEGORY_LABELS = {
        "AI Tools": [
          "AI Tools", "Artificial Intelligence", "Productivity Tools", "Students",
          "Note Taking", "Presentation Tools", "Image Generation", "Creative Tools",
          "Video Generation", "Research Tools", "Writing Tools", "AI Agents",
          "AI Chatbots", "AI Coding"
        ],
        "Coding Websites": [
          "Coding Websites", "Programming", "Learning Resources", "Coding", "Beginners"
        ],
        "Software": [
          "Software", "Technology Tools", "Online Tools", "PDF Tools",
          "Image Editing", "Video Editing", "File Sharing", "Creative Tools",
          "Productivity Tools"
        ],
        "Developer Tools": [
          "Developer Tools", "Git", "GitHub", "Software Development", "Coding",
          "Programming", "Developer Skills", "Linux", "Hosting"
        ],
        "Guides": [
          "Guides", "Beginners", "Coding", "Programming", "Artificial Intelligence",
          "AI Agents", "AI Chatbots", "AI Development", "AI Coding",
          "Vibe Coding", "Security Guides", "Technology Skills"
        ],
        "Roadmaps": [
          "Roadmaps", "Python", "Java", "JavaScript", "Data Structures", "Algorithms",
          "SQL", "Data Analytics", "Linux", "Full Stack Development", "DevOps",
          "Cloud", "Cybersecurity", "Cloud Computing", "Machine Learning",
          "AI Engineering", "AI Agents", "TypeScript", "React", "Node.js",
          "Frontend Development", "Backend Development", "Developer Skills", "IT Skills"
        ],
        "Resources": [
          "Resources", "Learning Resources", "Students", "Coding Projects",
          "Projects", "Hosting", "Developer Tools", "Technology Tools",
          "Online Tools", "Career Resources"
        ],
        "Technology": [
          "Technology", "Technology Tools", "Software", "Online Tools",
          "Productivity Tools", "Technology Skills"
        ],
        "Career & Jobs": [
          "Career & Jobs", "Resume", "Freshers", "Career Resources", "IT Skills",
          "Data Analyst", "Security Analyst", "Cloud Engineer", "Developer Skills",
          "IT Jobs", "Career Guide", "Entry Level Jobs", "Portfolio", "Projects"
        ],
        "Cybersecurity": [
          "Cybersecurity", "Data Protection", "Privacy", "Online Security",
          "Security Guides", "Security Analyst", "IT Skills"
        ]
      };

      function normalizeLabel(str) {
        return (str || '').toString().toLowerCase().trim().replace(/\s+/g, ' ');
      }

      var NORMALIZED_CATEGORY_LABELS = {};
      for (var cat in CATEGORY_LABELS) {
        if (CATEGORY_LABELS.hasOwnProperty(cat)) {
          NORMALIZED_CATEGORY_LABELS[cat] = new Set(CATEGORY_LABELS[cat].map(normalizeLabel));
        }
      }

      function getPrimaryCat(categories) {
        if (!categories || categories.length === 0) return 'Technology';
        var normCats = categories.map(normalizeLabel);
        var mainCats = [
          'AI Tools', 'Coding Websites', 'Software', 'Developer Tools',
          'Guides', 'Roadmaps', 'Resources', 'Technology', 'Career & Jobs', 'Cybersecurity'
        ];
        for (var i = 0; i < mainCats.length; i++) {
          var targetSet = NORMALIZED_CATEGORY_LABELS[mainCats[i]];
          if (targetSet) {
            for (var j = 0; j < normCats.length; j++) {
              if (targetSet.has(normCats[j])) return mainCats[i];
            }
          }
        }
        return categories[0];
      }

      function filterPostsByCategory(category, posts) {
        var source = posts || allArticlesList;
        if (!category || category === 'all') {
          return source.slice();
        }
        var targetSet = NORMALIZED_CATEGORY_LABELS[category];
        if (!targetSet) return [];

        var seen = new Set();
        var matched = [];

        for (var i = 0; i < source.length; i++) {
          var post = source[i];
          var id = post.url || post.title || i;
          if (seen.has(id)) continue;

          var labels = post.normalizedLabels;
          if (!labels && post.categories) {
            labels = post.categories.map(normalizeLabel);
            post.normalizedLabels = labels;
          }
          if (labels) {
            for (var j = 0; j < labels.length; j++) {
              if (targetSet.has(labels[j])) {
                seen.add(id);
                matched.push(post);
                break;
              }
            }
          }
        }
        return matched;
      }

      var currentFilter = 'all';
      var currentSort = 'newest';
      var currentSearch = '';
      var allArticlesList = [];
      var currentPage = 1;
      var PAGE_SIZE = 10;

      function renderPagination(totalPages, page) {
        var pagEl = document.getElementById('vtj-articles-pagination');
        if (!pagEl) return;

        if (totalPages <= 1) {
          pagEl.style.display = 'none';
          pagEl.innerHTML = '';
          return;
        }

        pagEl.style.display = 'flex';

        var html = '<div class="vtj-articles-pagination-inner">';

        // Prev Button
        if (page > 1) {
          html += '<button type="button" class="vtj-page-btn vtj-page-prev" data-page="' + (page - 1) + '" aria-label="Previous Page">&laquo; Prev</button>';
        } else {
          html += '<button type="button" class="vtj-page-btn vtj-page-prev disabled" disabled aria-label="Previous Page">&laquo; Prev</button>';
        }

        // Page Numbers
        var pages = [];
        if (totalPages <= 7) {
          for (var p = 1; p <= totalPages; p++) pages.push(p);
        } else {
          pages.push(1);
          if (page > 3) pages.push('...');
          var start = Math.max(2, page - 1);
          var end = Math.min(totalPages - 1, page + 1);
          for (var p = start; p <= end; p++) {
            if (pages.indexOf(p) === -1) pages.push(p);
          }
          if (page < totalPages - 2) pages.push('...');
          if (pages.indexOf(totalPages) === -1) pages.push(totalPages);
        }

        for (var i = 0; i < pages.length; i++) {
          var item = pages[i];
          if (item === '...') {
            html += '<span class="vtj-page-dots">&hellip;</span>';
          } else if (item === page) {
            html += '<button type="button" class="vtj-page-btn vtj-page-num active" data-page="' + item + '" aria-current="page">' + item + '</button>';
          } else {
            html += '<button type="button" class="vtj-page-btn vtj-page-num" data-page="' + item + '">' + item + '</button>';
          }
        }

        // Next Button
        if (page < totalPages) {
          html += '<button type="button" class="vtj-page-btn vtj-page-next" data-page="' + (page + 1) + '" aria-label="Next Page">Next Page &raquo;</button>';
        } else {
          html += '<button type="button" class="vtj-page-btn vtj-page-next disabled" disabled aria-label="Next Page">Next Page &raquo;</button>';
        }

        html += '</div>';
        pagEl.innerHTML = html;

        // Attach pagination click handlers
        var btns = pagEl.querySelectorAll('.vtj-page-btn:not(.disabled):not(.active)');
        for (var b = 0; b < btns.length; b++) {
          btns[b].addEventListener('click', function() {
            var target = parseInt(this.getAttribute('data-page'), 10);
            if (!isNaN(target) && target !== currentPage) {
              currentPage = target;
              renderArticles();
              var anchor = document.getElementById('vtj-articles-toolbar') || document.getElementById('articles-page-grid');
              if (anchor) {
                anchor.scrollIntoView({ behavior: 'smooth', block: 'start' });
              }
            }
          });
        }
      }

      function renderArticles() {
        var grid = document.getElementById('articles-page-grid');
        var spotlight = document.getElementById('vtj-articles-spotlight');
        var empty = document.getElementById('vtj-articles-empty-state');
        var emptyTitle = empty ? empty.querySelector('.vtj-articles-empty-title') : null;
        var emptyDesc = empty ? empty.querySelector('.vtj-articles-empty-desc') : null;
        var countEl = document.getElementById('vtj-articles-current-count');
        var totalEl = document.getElementById('vtj-articles-total-count');
        var resetBtn = document.getElementById('vtj-articles-reset-link');
        var statTotal = document.getElementById('vtj-stat-total-articles');
        var pillCountAll = document.getElementById('vtj-pill-count-all');
        var pagEl = document.getElementById('vtj-articles-pagination');

        if (statTotal) statTotal.textContent = allArticlesList.length;
        if (pillCountAll) pillCountAll.textContent = allArticlesList.length;
        if (totalEl) totalEl.textContent = allArticlesList.length;

        // Reusable category filtering
        var categoryFiltered = filterPostsByCategory(currentFilter);

        // Search query filtering
        var filtered = categoryFiltered.filter(function(post) {
          if (!currentSearch) return true;
          var q = currentSearch.toLowerCase();
          var t = (post.title || '').toLowerCase();
          var s = (post.summary || '').toLowerCase();
          var c = (post.categories || []).join(' ').toLowerCase();
          return t.indexOf(q) !== -1 || s.indexOf(q) !== -1 || c.indexOf(q) !== -1;
        });

        // Sorting
        filtered.sort(function(a, b) {
          if (currentSort === 'newest') return (b.rawDate || '').localeCompare(a.rawDate || '');
          if (currentSort === 'oldest') return (a.rawDate || '').localeCompare(b.rawDate || '');
          if (currentSort === 'title-asc') return (a.title || '').localeCompare(b.title || '');
          if (currentSort === 'title-desc') return (b.title || '').localeCompare(a.title || '');
          return 0;
        });

        if (resetBtn) resetBtn.style.display = (currentFilter !== 'all' || currentSearch) ? 'inline-flex' : 'none';

        if (filtered.length === 0) {
          if (countEl) countEl.textContent = '0';
          if (spotlight) spotlight.style.display = 'none';
          if (grid) grid.innerHTML = '';
          if (pagEl) pagEl.style.display = 'none';
          if (empty) {
            empty.style.display = 'block';
            if (currentSearch) {
              if (emptyTitle) emptyTitle.textContent = 'No articles found';
              if (emptyDesc) emptyDesc.textContent = "We couldn't find any articles matching your search criteria. Try different keywords or reset your filters.";
            } else {
              if (emptyTitle) emptyTitle.textContent = 'No posts found in this category.';
              if (emptyDesc) emptyDesc.textContent = 'There are currently no published articles under the ' + currentFilter + ' category.';
            }
          }
          return;
        }
        if (empty) empty.style.display = 'none';

        var totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
        if (currentPage > totalPages) currentPage = totalPages;
        if (currentPage < 1) currentPage = 1;

        var displayList = [];
        var hasSpotlight = (currentFilter === 'all' && !currentSearch && filtered.length > 0);

        if (hasSpotlight) {
          if (currentPage === 1) {
            var spot = filtered[0];
            if (spotlight) {
              spotlight.style.display = 'grid';
              var sImg = document.getElementById('vtj-spotlight-img');
              if (sImg) { sImg.src = spot.img; sImg.alt = spot.title; }
              var sCat = document.getElementById('vtj-spotlight-cat');
              if (sCat) sCat.textContent = spot.primaryCat;
              var sDate = document.getElementById('vtj-spotlight-date');
              if (sDate) sDate.textContent = spot.date;
              var sRead = document.getElementById('vtj-spotlight-readtime');
              if (sRead) sRead.textContent = spot.readTime;
              var sLink = document.getElementById('vtj-spotlight-title-link');
              if (sLink) { sLink.textContent = spot.title; sLink.href = spot.url; }
              var sDesc = document.getElementById('vtj-spotlight-desc');
              if (sDesc) sDesc.textContent = spot.summary;
              var sCta = document.getElementById('vtj-spotlight-cta');
              if (sCta) sCta.href = spot.url;
            }
            displayList = filtered.slice(1, PAGE_SIZE);
          } else {
            if (spotlight) spotlight.style.display = 'none';
            var startIdx = (currentPage - 1) * PAGE_SIZE;
            var endIdx = startIdx + PAGE_SIZE;
            displayList = filtered.slice(startIdx, endIdx);
          }
        } else {
          if (spotlight) spotlight.style.display = 'none';
          var startIdx = (currentPage - 1) * PAGE_SIZE;
          var endIdx = startIdx + PAGE_SIZE;
          displayList = filtered.slice(startIdx, endIdx);
        }

        if (countEl) {
          var fromNum = (currentPage - 1) * PAGE_SIZE + 1;
          var toNum = Math.min(currentPage * PAGE_SIZE, filtered.length);
          countEl.textContent = (fromNum === toNum) ? fromNum : (fromNum + ' \u2013 ' + toNum);
        }

        var html = '';
        for (var i = 0; i < displayList.length; i++) {
          var p = displayList[i];
          var safeT = escapeHtml(p.title);
          var safeS = escapeHtml(p.summary);

          html += '<article class="vtj-article-card">' +
            '<div class="vtj-article-thumb-wrap">' +
              '<a href="' + p.url + '" aria-label="Read ' + safeT + '">' +
                '<img class="vtj-article-thumb-img" src="' + p.img + '" alt="' + safeT + '" loading="lazy" width="400" height="225"/>' +
              '</a>' +
            '</div>' +
            '<div class="vtj-article-card-body">' +
              '<div class="vtj-article-top-meta">' +
                '<span class="vtj-article-cat-pill">' + p.primaryCat + '</span>' +
                '<span class="vtj-article-read-time">' +
                  '<svg viewBox="0 0 24 24" style="width:11px;height:11px;fill:currentColor"><path d="M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10 10-4.5 10-10S17.5 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm.5-13H11v6l5.2 3.2.8-1.3-4.5-2.7V7z"/></svg>' +
                  p.readTime +
                '</span>' +
              '</div>' +
              '<h3 class="vtj-article-title"><a href="' + p.url + '">' + safeT + '</a></h3>' +
              '<p class="vtj-article-snippet">' + safeS + '</p>' +
              '<div class="vtj-article-card-footer">' +
                '<a href="' + p.url + '" class="vtj-article-read-btn">' +
                  'Read Guide' +
                  '<svg viewBox="0 0 24 24"><path d="M5 12h14M12 5l7 7-7 7"/></svg>' +
                '</a>' +
                '<span class="vtj-article-card-date">' +
                  '<svg viewBox="0 0 24 24"><path d="M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-1.99.9-1.99 2L3 20a2 2 0 002 2h14c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 16H5V9h14v11z"/></svg>' +
                  p.date +
                '</span>' +
              '</div>' +
            '</div>' +
          '</article>';
        }
        if (grid) grid.innerHTML = html;

        renderPagination(totalPages, currentPage);
      }

      function setupEvents() {
        var pillsBar = document.getElementById('vtj-articles-pills-bar');
        if (pillsBar) {
          pillsBar.addEventListener('click', function(e) {
            var btn = e.target.closest('.vtj-articles-pill-btn');
            if (!btn) return;
            var pills = pillsBar.querySelectorAll('.vtj-articles-pill-btn');
            for (var j = 0; j < pills.length; j++) pills[j].classList.remove('active');
            btn.classList.add('active');
            currentFilter = btn.getAttribute('data-category') || 'all';
            currentPage = 1;
            renderArticles();
          });
        }

        var searchIn = document.getElementById('vtj-articles-search-input');
        var searchClr = document.getElementById('vtj-articles-search-clear');
        if (searchIn) {
          searchIn.addEventListener('input', function() {
            currentSearch = searchIn.value.trim();
            if (searchClr) searchClr.style.display = currentSearch ? 'flex' : 'none';
            currentPage = 1;
            renderArticles();
          });
        }
        if (searchClr) {
          searchClr.addEventListener('click', function() {
            if (searchIn) searchIn.value = '';
            currentSearch = '';
            searchClr.style.display = 'none';
            currentPage = 1;
            renderArticles();
          });
        }

        var sortSel = document.getElementById('vtj-articles-sort-select');
        if (sortSel) {
          sortSel.addEventListener('change', function(e) {
            currentSort = e.target.value;
            currentPage = 1;
            renderArticles();
          });
        }

        function resetFilters() {
          currentFilter = 'all';
          currentSearch = '';
          currentPage = 1;
          if (searchIn) searchIn.value = '';
          if (searchClr) searchClr.style.display = 'none';
          var pills = document.querySelectorAll('.vtj-articles-pill-btn');
          for (var p = 0; p < pills.length; p++) {
            pills[p].classList.toggle('active', pills[p].getAttribute('data-category') === 'all');
          }
          renderArticles();
        }

        var resetLnk = document.getElementById('vtj-articles-reset-link');
        if (resetLnk) resetLnk.addEventListener('click', resetFilters);
        var emptyBtn = document.getElementById('vtj-articles-empty-reset-btn');
        if (emptyBtn) emptyBtn.addEventListener('click', resetFilters);
      }

      var totalPostsCount = 0;
      var eventsSetupDone = false;

      function parseEntry(e) {
        var title = e.title ? e.title.$t : '';
        var url = getUrl(e);
        var rawDate = e.published ? e.published.$t : '';
        var date = formatDate(rawDate);
        var categories = [];
        if (e.category) {
          for (var c = 0; c < e.category.length; c++) {
            if (e.category[c].term) categories.push(e.category[c].term);
          }
        }
        var normalizedLabels = categories.map(normalizeLabel);
        var primaryCat = getPrimaryCat(categories);
        var img = getFirstImgSrc(e);
        var summary = '';
        if (e.summary && e.summary.$t) {
          summary = e.summary.$t.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
        } else if (e.content && e.content.$t) {
          summary = e.content.$t.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
        }
        if (summary.length > 175) {
          summary = summary.substring(0, 175).trim() + '...';
        }
        var readTime = getReadingTime(e) + ' min read';

        return {
          title: title,
          url: url,
          rawDate: rawDate,
          date: date,
          categories: categories,
          normalizedLabels: normalizedLabels,
          primaryCat: primaryCat,
          img: img,
          summary: summary,
          readTime: readTime
        };
      }

      function updateCategoryPillCounts() {
        var pillCountAll = document.getElementById('vtj-pill-count-all');
        if (pillCountAll) pillCountAll.textContent = allArticlesList.length;

        var pills = document.querySelectorAll('.vtj-articles-pill-btn');
        for (var j = 0; j < pills.length; j++) {
          var catKey = pills[j].getAttribute('data-category');
          if (!catKey || catKey === 'all') continue;
          var countVal = filterPostsByCategory(catKey).length;
          var countSpan = pills[j].querySelector('.vtj-articles-pill-count');
          if (countSpan) {
            countSpan.textContent = countVal;
          } else {
            var span = document.createElement('span');
            span.className = 'vtj-articles-pill-count';
            span.textContent = countVal;
            pills[j].appendChild(span);
          }
        }
      }

      function fetchFeedBatch(startIndex) {
        var callbackName = 'vtjArticlesBatch_' + startIndex;
        window[callbackName] = function(data) {
          try { delete window[callbackName]; } catch(e) {}

          var feed = data && data.feed ? data.feed : {};
          if (feed.openSearch$totalResults && feed.openSearch$totalResults.$t) {
            var tr = parseInt(feed.openSearch$totalResults.$t, 10);
            if (!isNaN(tr) && tr > 0) totalPostsCount = tr;
          }

          var entries = feed.entry || [];
          for (var i = 0; i < entries.length; i++) {
            allArticlesList.push(parseEntry(entries[i]));
          }

          if (allArticlesList.length === 0 && entries.length === 0) {
            var g = document.getElementById('articles-page-grid');
            if (g) g.innerHTML = '<p style="color:var(--text-muted);text-align:center;padding:3rem 0;grid-column:1/-1;">No articles found.</p>';
            return;
          }

          if (!eventsSetupDone) {
            setupEvents();
            eventsSetupDone = true;
          }

          updateCategoryPillCounts();
          renderArticles();

          // Auto-paginate until ALL posts are fetched!
          if (entries.length > 0 && allArticlesList.length < totalPostsCount) {
            var nextIndex = allArticlesList.length + 1;
            fetchFeedBatch(nextIndex);
          }
        };

        var s = document.createElement("script");
        s.src = BLOG_URL + "feeds/posts/summary?alt=json-in-script&start-index=" + startIndex + "&max-results=50&callback=" + callbackName;
        document.body.appendChild(s);
      }

      // Initial batch fetch starting at index 1
      fetchFeedBatch(1);

      setTimeout(function() {
        var skel = document.querySelector('.vtj-article-skeleton-card');
        if (skel && allArticlesList.length === 0) {
          var g = document.getElementById('articles-page-grid');
          if (g) g.innerHTML = '<p style="color:var(--text-muted);text-align:center;padding:3rem 0;grid-column:1/-1;">Unable to load articles feed. Please refresh or try again later.</p>';
        }
      }, 7000);
    }

    /* ====================================================
       SINGLE POST FEATURES
    ==================================================== */
    function initSinglePost() {
      /* Author avatar - use header logo */
      var logoImg = document.getElementById('header-logo-img');
      if (logoImg) {
        var postAvatar = document.getElementById('post-author-avatar-img');
        if (postAvatar) { postAvatar.src = logoImg.src; postAvatar.style.display = ''; }
        var bioAvatar = document.getElementById('author-bio-avatar-img');
        if (bioAvatar) { bioAvatar.src = logoImg.src; bioAvatar.style.display = ''; }
      }

      /* Copy link */
      var copyBtn = document.getElementById("share-copy-btn");
      if (copyBtn) {
        copyBtn.addEventListener("click", function() {
          var url = copyBtn.getAttribute("data-url") || window.location.href;
          if (navigator.clipboard) {
            navigator.clipboard.writeText(url).then(function() { copyBtn.title = "Copied!"; setTimeout(function() { copyBtn.title = "Copy link"; }, 2000); });
          } else {
            var ta = document.createElement("textarea");
            ta.value = url;
            document.body.appendChild(ta);
            ta.select();
            document.execCommand("copy");
            document.body.removeChild(ta);
          }
        });
      }

/* ============================================================
       BLOG POST / ARTICLE PAGE DYNAMIC FEATURES
    ============================================================ */
    (function () {
      if (!document.body.classList.contains('item-view') && !document.querySelector('.vtj-post-card')) {
        return;
      }

      var postContent = document.getElementById('post-content');
      if (!postContent) return;

      // 1. DYNAMIC READING TIME CALCULATOR
      var readTimeEl = document.getElementById('vtj-read-time');
      if (readTimeEl && postContent) {
        var text = postContent.innerText || postContent.textContent || '';
        var words = text.trim().split(/\s+/).filter(Boolean).length;
        var minutes = Math.max(1, Math.ceil(words / 200));
        readTimeEl.textContent = minutes + ' min read';
      }

      // 2. SOCIAL SHARE BUTTONS & COPY LINK
      var copyBtn = document.getElementById('vtj-share-copy-btn');
      if (copyBtn) {
        copyBtn.addEventListener('click', function (e) {
          e.preventDefault();
          var url = window.location.href;
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(url).then(function () {
              showCopySuccess(copyBtn);
            });
          } else {
            var temp = document.createElement('input');
            temp.value = url;
            document.body.appendChild(temp);
            temp.select();
            document.execCommand('copy');
            document.body.removeChild(temp);
            showCopySuccess(copyBtn);
          }
        });
      }

      function showCopySuccess(btn) {
        var originalTitle = btn.getAttribute('title') || 'Copy Link';
        btn.setAttribute('title', 'Copied!');
        btn.classList.add('is-copied');
        setTimeout(function () {
          btn.setAttribute('title', originalTitle);
          btn.classList.remove('is-copied');
        }, 2000);
      }

      // 3. TABLE OF CONTENTS GENERATOR (H1, H2 ONLY; IF NO H1, SHOW ONLY H2; NEVER H3)
      // Hide static page duplicate title if hero banner exists
      var staticHero = document.querySelector('.vtj-static-page-card .vtj-page-hero, .vtj-static-page-layout .vtj-page-hero, .vtj-static-page');
      var staticTitle = document.getElementById('vtj-static-title');
      if (staticHero && staticTitle) {
        staticTitle.style.display = 'none';
      }

      var tocCard = document.getElementById('vtj-toc-card');
      var tocList = document.getElementById('vtj-post-toc-list');
      var tocRail = document.getElementById('vtj-toc-rail');
      if (tocCard && tocList && postContent) {
        // Plain in-post manual TOC hiding if present
        var allLists = postContent.querySelectorAll('ul, ol');
        for (var j = 0; j < allLists.length; j++) {
          var listPrev = allLists[j].previousElementSibling;
          if (listPrev && (listPrev.tagName.toLowerCase() === 'h1' || listPrev.tagName.toLowerCase() === 'h2' || listPrev.tagName.toLowerCase() === 'h3') && listPrev.textContent.toLowerCase().indexOf('table of contents') !== -1) {
            allLists[j].style.display = 'none';
            listPrev.style.display = 'none';
          }
        }

        // Check if H1 exists inside post body
        var allH1s = postContent.querySelectorAll('h1');
        var rawHeadings;
        if (allH1s.length > 0) {
          // If H1 exists, show only H1 and H2
          rawHeadings = postContent.querySelectorAll('h1, h2');
        } else {
          // If H1 does not exist, show ONLY H2 (never H3)
          rawHeadings = postContent.querySelectorAll('h2');
        }

        var validHeadings = [];
        for (var i = 0; i < rawHeadings.length; i++) {
          var h = rawHeadings[i];
          var tag = h.tagName.toLowerCase();
          // Guarantee strictly only h1 and h2
          if (tag !== 'h1' && tag !== 'h2') continue;
          if (h.closest('.vtj-code-block') || h.closest('pre')) continue;
          var txt = (h.textContent || '').trim();
          if (!txt || txt.toLowerCase().indexOf('table of contents') !== -1) continue;
          validHeadings.push(h);
        }

        if (validHeadings.length >= 2) {
          tocList.innerHTML = '';
          var tocItems = [];
          validHeadings.forEach(function (h, idx) {
            var txt = (h.textContent || '').trim();
            if (!h.id) {
              h.id = 'section-heading-' + idx;
            }
            var isH1 = h.tagName.toLowerCase() === 'h1';
            var item = document.createElement('a');
            item.href = '#' + h.id;
            item.className = 'vtj-toc-item ' + (isH1 ? 'toc-level-h1' : 'toc-level-h2');
            item.textContent = txt;
            item.setAttribute('data-target', h.id);

            item.addEventListener('click', function (e) {
              e.preventDefault();
              var target = document.getElementById(h.id);
              if (target) {
                var offset = 80;
                var bodyRect = document.body.getBoundingClientRect().top;
                var elementRect = target.getBoundingClientRect().top;
                var elementPosition = elementRect - bodyRect;
                var offsetPosition = elementPosition - offset;
                window.scrollTo({
                  top: offsetPosition,
                  behavior: 'smooth'
                });
                history.pushState(null, null, '#' + h.id);
              }
            });

            tocList.appendChild(item);
            tocItems.push(item);
          });

          // IntersectionObserver for active section highlight
          if ('IntersectionObserver' in window) {
            var observer = new IntersectionObserver(function (entries) {
              entries.forEach(function (entry) {
                if (entry.isIntersecting) {
                  var id = entry.target.id;
                  tocItems.forEach(function (link) {
                    if (link.getAttribute('data-target') === id) {
                      link.classList.add('active');
                    } else {
                      link.classList.remove('active');
                    }
                  });
                }
              });
            }, {
              rootMargin: '-80px 0px -60% 0px',
              threshold: 0
            });

            validHeadings.forEach(function (h) {
              observer.observe(h);
            });
          }
        } else {
          if (tocRail) tocRail.style.display = 'none';
          else tocCard.style.display = 'none';
        }
      }

      // 4. RESPONSIVE TABLES WRAPPER
      var tables = postContent.querySelectorAll('table');
      tables.forEach(function (tbl) {
        if (!tbl.parentElement.classList.contains('vtj-post-table-scroll')) {
          var wrapper = document.createElement('div');
          wrapper.className = 'vtj-post-table-scroll';
          tbl.parentNode.insertBefore(wrapper, tbl);
          wrapper.appendChild(tbl);
        }
      });

      // 5. MUST READ SIDEBAR ARTICLES LOADER
      var mustReadList = document.getElementById('vtj-post-mustread-list');
      if (mustReadList) {
        window.vtjMustReadCallback = function (data) {
          if (!data || !data.feed || !data.feed.entry) return;
          var entries = data.feed.entry;
          var currentUrl = window.location.href.split('?')[0].split('#')[0];
          var html = '';
          var count = 0;

          for (var i = 0; i < entries.length && count < 3; i++) {
            var entry = entries[i];
            var postUrl = '';
            if (entry.link) {
              for (var j = 0; j < entry.link.length; j++) {
                if (entry.link[j].rel === 'alternate') {
                  postUrl = entry.link[j].href;
                  break;
                }
              }
            }

            if (!postUrl || postUrl.split('?')[0].split('#')[0] === currentUrl) continue;

            var title = entry.title ? entry.title.$t : 'Article';
            var published = entry.published ? entry.published.$t : '';
            var dateStr = '';
            if (published) {
              var d = new Date(published);
              dateStr = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
            }
            var authorName = (entry.author && entry.author[0] && entry.author[0].name) ? entry.author[0].name.$t : 'Vicky TJ';

            var thumb = 'https://blogger.googleusercontent.com/img/a/AVvXsEjN5b4wB-x3e1tQ_L5v7B9W0C1d2E3f4G5h6I7j8K9l0M1n2O3p4Q5r6S7t8U9v0W1x2Y3z=w200-h140-c-rw';
            if (entry.media$thumbnail && entry.media$thumbnail.url) {
              thumb = entry.media$thumbnail.url.replace('/s72-c/', '/w200-h140-c-rw/');
            } else if (entry.content && entry.content.$t) {
              var m = entry.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
              if (m && m[1]) thumb = m[1];
            }

            html += '<a class="vtj-mustread-item" href="' + postUrl + '">' +
              '<img class="vtj-mustread-thumb" src="' + thumb + '" alt="' + title.replace(/"/g, '&quot;') + '" loading="lazy" width="72" height="54"/>' +
              '<div class="vtj-mustread-info">' +
                '<h4 class="vtj-mustread-title">' + title + '</h4>' +
                '<span class="vtj-mustread-meta">By ' + authorName + (dateStr ? ' / ' + dateStr : '') + '</span>' +
              '</div>' +
            '</a>';
            count++;
          }

          if (html) {
            mustReadList.innerHTML = html;
          }
        };

        var script = document.createElement('script');
        script.src = (window.location.origin || '') + '/feeds/posts/summary?alt=json-in-script&max-results=8&callback=vtjMustReadCallback';
        script.async = true;
        document.head.appendChild(script);
      }
    })();

      /* Post table: safe horizontal scroll wrapping only (no row removal, no reordering, no thead/tbody changes) */
      var postContentEl = document.getElementById('post-content');

      if (postContentEl) {
        var postTables = postContentEl.querySelectorAll('table');

        for (var tableIndex = 0; tableIndex < postTables.length; tableIndex++) {
          var currentTable = postTables[tableIndex];

          if (
            !currentTable.parentElement ||
            !currentTable.parentElement.classList.contains('post-table-scroll')
          ) {
            var tableWrapper = document.createElement('div');
            tableWrapper.className = 'post-table-scroll';

            currentTable.parentNode.insertBefore(tableWrapper, currentTable);
            tableWrapper.appendChild(currentTable);
          }

          currentTable.classList.add('vtj-post-table');
        }
      }

      /* ========================================
         Related Posts Carousel - High Resolution Images
         Fixed: Uses same image method as Articles page (getFirstImgSrc)
         ======================================== */
      (function() {
        var relSection = document.getElementById("related-section");
        var relTrack = document.getElementById("related-track");
        if (!relSection || !relTrack) return;

        // ========== Configuration ==========
        var CAROUSEL_CONFIG = {
          postCount: 10,
          placeholderImage: 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&auto=format&fit=crop&q=70'
        };

        // ========== High-Resolution Image Function (Same as Articles Page) ==========
        // This extracts first image from content and converts to s1200 for sharp quality
        function getHighResImage(entry) {
          var content = (entry.content && entry.content.$t) || '';
          if (content) {
            var cm = content.match(/<img[^>]+src=["']([^"']+)["']/i);
            if (cm && cm[1] && cm[1].indexOf('data:') !== 0) {
              return cm[1]
                .replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/')
                .replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/')
                .replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/')
                .replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw')
                .replace(/=s\d+.*$/, '=w800-h450-c-rw');
            }
          }
          if (entry.media$thumbnail && entry.media$thumbnail.url) {
            return entry.media$thumbnail.url
              .replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/')
              .replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/')
              .replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/')
              .replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw')
              .replace(/=s\d+.*$/, '=w800-h450-c-rw');
          }
          var summary = (entry.summary && entry.summary.$t) || '';
          if (summary) {
            var sm = summary.match(/<img[^>]+src=["']([^"']+)["']/i);
            if (sm && sm[1]) return sm[1];
          }
          return CAROUSEL_CONFIG.placeholderImage;
        }

        // ========== Srcset Generator (Same as Articles Page) ==========
        // Creates responsive srcset for different screen sizes
        function imgSrcset(url) {
          var s1 = url.replace(/\/s\d+(-c)?\//, '/w400-h225-c-rw/').replace(/\/w\d+-h\d+(-c)?\//, '/w400-h225-c-rw/').replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w400-h225-c-rw/').replace(/=s\d+.*$/, '=w400-h225-c-rw').replace(/=w\d+-h\d+.*$/, '=w400-h225-c-rw');
          var s2 = url.replace(/\/s\d+(-c)?\//, '/w800-h450-c-rw/').replace(/\/w\d+-h\d+(-c)?\//, '/w800-h450-c-rw/').replace(/\/w\d+-h\d+-p-k-no-nu\//, '/w800-h450-c-rw/').replace(/=s\d+.*$/, '=w800-h450-c-rw').replace(/=w\d+-h\d+.*$/, '=w800-h450-c-rw');
          return s1 + ' 400w, ' + s2 + ' 800w';
        }

        // ========== Get Post URL ==========
        function getPostUrl(entry) {
          if (!entry) return "#";
          if (entry.link) {
            for (var i = 0; i < entry.link.length; i++) {
              if (entry.link[i].rel === "alternate") return entry.link[i].href;
            }
          }
          return "#";
        }

        // ========== Get Current Post ID for Exclusion ==========
        function getCurrentPostId() {
          var path = window.location.pathname;
          var match = path.match(/\/(\d{4})\/(\d{2})\/([^/.]+)/);
          return match ? match[3] : path;
        }

        // ========== Shuffle Array (Randomization) ==========
        function shuffleArray(array) {
          var shuffled = array.slice();
          for (var i = shuffled.length - 1; i > 0; i--) {
            var j = Math.floor(Math.random() * (i + 1));
            var temp = shuffled[i];
            shuffled[i] = shuffled[j];
            shuffled[j] = temp;
          }
          return shuffled;
        }

        // ========== Main Callback ==========
        window.vtjCarouselCb = function(data) {
          // Hide section if no data
          if (!data || !data.feed || !data.feed.entry) {
            relSection.style.display = "none";
            return;
          }

          var entries = data.feed.entry;
          var currentPostId = getCurrentPostId();
          var validPosts = [];
          var seenUrls = {};

          // Filter valid posts (exclude current, remove duplicates)
          for (var i = 0; i < entries.length; i++) {
            var entry = entries[i];
            var url = getPostUrl(entry);
            if (url === "#" || !url) continue;
            if (seenUrls[url]) continue;
            if (currentPostId && url.indexOf(currentPostId) !== -1) continue;
            seenUrls[url] = true;
            validPosts.push(entry);
          }

          // Randomize and limit to configured count
          var randomizedPosts = shuffleArray(validPosts);
          var selectedPosts = randomizedPosts.slice(0, CAROUSEL_CONFIG.postCount);

          // Hide if fewer than 2 posts
          if (selectedPosts.length < 2) {
            relSection.style.display = "none";
            return;
          }

          // Build HTML with HIGH-RESOLUTION IMAGES
          var html = "";
          for (var j = 0; j < selectedPosts.length; j++) {
            var post = selectedPosts[j];
            var postUrl = getPostUrl(post);
            var postTitle = (post.title && post.title.$t) ? post.title.$t : "Untitled Post";

            // USE HIGH-RESOLUTION IMAGE FUNCTION (Same as Articles Page)
            var img = getHighResImage(post);
            var srcsetAttr = imgSrcset(img);

            var safeTitle = escapeHtml(postTitle);
            // Build card with srcset, sizes, width, height attributes
            html += "<div class='related-card'>";
            html += "<div class='related-card-img'>";
            html += "<a href='" + postUrl + "' aria-label='Open " + safeTitle + "'>";
            // HIGH-QUALITY IMAGE with srcset for responsive sizes
            html += "<img src='" + img + "' alt='" + safeTitle + "' loading='lazy' decoding='async' width='400' height='225' srcset='" + srcsetAttr + "' sizes='(max-width: 640px) 400px, 400px'/>";
            html += "</a>";
            html += "</div>";
            html += "<div class='related-card-body'>";
            html += "<p class='related-card-title'><a href='" + postUrl + "'>" + postTitle + "</a></p>";
            html += "</div>";
            html += "</div>";
          }

          // Duplicate for seamless infinite scroll
          relTrack.innerHTML = html + html;
          relTrack.parentNode.classList.remove("paused");
        };

        // ========== Load Posts ==========
        var blogUrl = document.body.getAttribute("data-url") || "/";
        if (blogUrl.indexOf("blogger.com") !== -1) blogUrl = "/";
        if (blogUrl.charAt(blogUrl.length - 1) !== "/") blogUrl += "/";

        var script = document.createElement("script");
        // Fetch more posts (50) to ensure we have enough after filtering
        script.src = blogUrl + "feeds/posts/summary?alt=json-in-script&max-results=50&callback=vtjCarouselCb";
        document.body.appendChild(script);

        // ========== Carousel Interactions ==========
        var carousel = document.getElementById("related-carousel");
        if (carousel) {
          // Pause on hover
          carousel.addEventListener("mouseenter", function() { this.classList.add("paused"); });
          carousel.addEventListener("mouseleave", function() { this.classList.remove("paused"); });

          // Touch/scroll support for mobile
          var touchStartX = 0, touchScrollLeft = 0, isTouching = false;
          carousel.addEventListener("touchstart", function(e) {
            if (e.touches.length === 1) {
              touchStartX = e.touches[0].clientX;
              touchScrollLeft = this.scrollLeft;
              isTouching = true;
              this.classList.add("paused");
            }
          }, { passive: true });

          carousel.addEventListener("touchmove", function(e) {
            if (isTouching && e.touches.length === 1) {
              this.scrollLeft = touchScrollLeft + (touchStartX - e.touches[0].clientX);
            }
          }, { passive: true });

          carousel.addEventListener("touchend", function() {
            isTouching = false;
            setTimeout(function() { carousel.classList.remove("paused"); }, 1000);
          }, { passive: true });
        }
      })();

      /* FAQ accordion - independent per section */
      var faqSections = document.querySelectorAll('.vtj-faq-section');

      for (var sectionIndex = 0; sectionIndex < faqSections.length; sectionIndex++) {
        (function (faqSection) {
          var faqQuestions = faqSection.querySelectorAll('.vtj-faq-question');

          for (var questionIndex = 0; questionIndex < faqQuestions.length; questionIndex++) {
            faqQuestions[questionIndex].addEventListener('click', function () {
              var clickedQuestion = this;
              var clickedItem = clickedQuestion.closest('.vtj-faq-item');
              var isAlreadyOpen = clickedItem.classList.contains('active');
              var allItems = faqSection.querySelectorAll('.vtj-faq-item');

              for (var itemIndex = 0; itemIndex < allItems.length; itemIndex++) {
                allItems[itemIndex].classList.remove('active');

                var itemQuestion =
                  allItems[itemIndex].querySelector('.vtj-faq-question');

                if (itemQuestion) {
                  itemQuestion.setAttribute('aria-expanded', 'false');
                }
              }

              if (!isAlreadyOpen) {
                clickedItem.classList.add('active');
                clickedQuestion.setAttribute('aria-expanded', 'true');
              }
            });
          }
        })(faqSections[sectionIndex]);
      }

      /* Initialize code blocks for single posts */
      initCodeBlocks();
    }

        /* ============================================================
       PREMIUM CODE BLOCKS SYSTEM - SYNTAX HIGHLIGHTING & COPY
    ============================================================ */
    function initCodeBlocks() {
      var postContainers = document.querySelectorAll('.post-content, #post-content, .post-body, .post-body-card, .vtj-post-body');
      if (!postContainers || !postContainers.length) return;

      var copyIconSvg = '<svg viewBox="0 0 24 24"><path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/></svg>';
      var checkIconSvg = '<svg viewBox="0 0 24 24"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/></svg>';

      function normalizeLang(lang) {
        if (!lang) return '';
        var l = lang.toLowerCase().trim().replace(/^language-|^lang-/, '');
        switch (l) {
          case 'js':
          case 'javascript':
            return 'JavaScript';
          case 'html':
          case 'htm':
          case 'xhtml':
          case 'xml':
            return 'HTML';
          case 'css':
            return 'CSS';
          case 'py':
          case 'python':
            return 'Python';
          case 'java':
            return 'Java';
          case 'sql':
            return 'SQL';
          case 'php':
            return 'PHP';
          case 'cpp':
          case 'c++':
            return 'C++';
          case 'cs':
          case 'csharp':
          case 'c#':
            return 'C#';
          case 'c':
            return 'C';
          case 'json':
            return 'JSON';
          case 'bash':
          case 'sh':
          case 'shell':
          case 'zsh':
            return 'Bash';
          case 'md':
          case 'markdown':
            return 'Markdown';
          case 'ts':
          case 'typescript':
            return 'TypeScript';
          case 'yaml':
          case 'yml':
            return 'YAML';
        }
        return l ? l.toUpperCase() : '';
      }

      function detectLanguage(preEl, codeEl) {
        var classString = '';
        if (preEl && preEl.className) classString += ' ' + preEl.className;
        if (codeEl && codeEl.className) classString += ' ' + codeEl.className;

        var matches = classString.match(/(?:lang|language)-([a-z0-9+#-]+)/i) || 
                      classString.match(/\b(html|css|javascript|js|python|py|java|sql|php|cpp|c\+\+|csharp|cs|c|json|bash|sh|shell|xml|markdown|md|typescript|ts)\b/i);

        if (matches) {
          var found = normalizeLang(matches[1] || matches[0]);
          if (found) return found;
        }

        var text = (codeEl || preEl).textContent.trim();
        if (/^<!DOCTYPE/i.test(text) || /^<html/i.test(text) || /^<div/i.test(text) || /^<svg/i.test(text)) return 'HTML';
        if (/^import\s+[\w{}*,\s]+\s+from/i.test(text) || /^const\s+|^let\s+|^var\s+/i.test(text) || /^function\s*\w*\s*\(/.test(text) || /=>/.test(text)) return 'JavaScript';
        if (/^def\s+\w+\s*\(|^import\s+\w+|^from\s+\w+\s+import/i.test(text)) return 'Python';
        if (/^public\s+class\s+|^class\s+\w+\s*\{|^import\s+java\./i.test(text) || /System\.out\.println/.test(text)) return 'Java';
        if (/^SELECT\s+|^INSERT\s+INTO|^UPDATE\s+|^DELETE\s+FROM|^CREATE\s+TABLE/i.test(text)) return 'SQL';
        if (/^<\?php/i.test(text)) return 'PHP';
        if (/^{\s*"|^\s*\[\s*{/i.test(text)) return 'JSON';
        if (/^curl\s+|^npm\s+|^pip\s+|^git\s+|^apt\s+|^sudo\s+/i.test(text)) return 'Bash';
        if (/^[.#]?[a-zA-Z0-9_-]+\s*\{\s*[a-zA-Z-]+:/i.test(text)) return 'CSS';

        return 'CODE';
      }

      function escapeHtml(str) {
        return str.replace(/&/g, '&amp;')
                  .replace(/</g, '&lt;')
                  .replace(/>/g, '&gt;')
                  .replace(/"/g, '&quot;')
                  .replace(/'/g, '&#39;');
      }

      /* Single-pass non-colliding syntax tokenizer */
      function highlightCode(code, lang) {
        var l = (lang || '').toLowerCase();

        var commentPattern = '\\/\\*([\\s\\S]*?)\\*\\/|\\/\\/(.*)';
        if (l === 'python' || l === 'py' || l === 'bash' || l === 'sh') {
          commentPattern = '#(.*)';
        } else if (l === 'html' || l === 'xml') {
          commentPattern = '<!--([\\s\\S]*?)-->';
        }

        var kwList = 'class|public|private|protected|static|final|void|int|float|double|boolean|char|byte|short|long|new|this|super|return|if|else|switch|case|default|break|continue|for|while|do|try|catch|finally|throw|throws|import|package|instanceof|interface|extends|implements|enum|abstract|synchronized|volatile|transient|native|strictfp|assert|const|goto|def|lambda|async|await|let|var|function|yield|typeof|null|undefined|true|false|None|True|False';

        if (l === 'sql') {
          kwList = 'SELECT|FROM|WHERE|INSERT|INTO|UPDATE|DELETE|JOIN|LEFT|RIGHT|INNER|OUTER|GROUP|BY|ORDER|HAVING|LIMIT|CREATE|TABLE|DROP|ALTER|ADD|COLUMN|PRIMARY|KEY|FOREIGN|REFERENCES|NOT|NULL|AND|OR|AS|IN|ON|SET|VALUES';
        } else if (l === 'bash' || l === 'sh') {
          kwList = 'if|then|else|elif|fi|case|esac|for|select|while|until|do|done|in|function|time|echo|exit|export|source|alias|cd|curl|bash|sudo|python|pip|npm|git';
        }

        var stringPattern = '"(?:[^"\\\\]|\\\\.)*"|\'(?:[^\'\\\\]|\\\\.)*\'|`(?:[^`\\\\]|\\\\.)*`';
        var tagPattern = (l === 'html' || l === 'xml') ? '(<\\/?[a-zA-Z0-9:-]+(?:\\s+[^>]*)?>)|' : '';

        var masterRegex = new RegExp(
          '(' + commentPattern + ')|' +
          '(' + stringPattern + ')|' +
          tagPattern +
          '(\\b\\d+(?:\\.\\d+)?\\b)|' +
          '(\\b(?:' + kwList + ')\\b)|' +
          '(\\b[A-Z][a-zA-Z0-9_$]*\\b)|' +
          '(\\b[a-zA-Z_$][a-zA-Z0-9_$]*(?=\\s*\\())|' +
          '([{}()\\[\\];,])',
          l === 'sql' ? 'gi' : 'g'
        );

        var result = '';
        var lastIndex = 0;
        var match;

        while ((match = masterRegex.exec(code)) !== null) {
          if (match.index > lastIndex) {
            result += escapeHtml(code.slice(lastIndex, match.index));
          }

          var text = match[0];

          if (match[1]) {
            result += '<span class="token comment">' + escapeHtml(text) + '</span>';
          } else if (text.charAt(0) === '"' || text.charAt(0) === "'" || text.charAt(0) === '`') {
            result += '<span class="token string">' + escapeHtml(text) + '</span>';
          } else if ((l === 'html' || l === 'xml') && text.charAt(0) === '<') {
            var isClose = text.indexOf('</') === 0;
            var openMatch = text.match(/^<\/?([a-zA-Z0-9:-]+)/);
            var tagName = openMatch ? openMatch[1] : '';
            var rest = text.slice(openMatch ? openMatch[0].length : 1, text.lastIndexOf('>'));
            var restHighlighted = rest.replace(/([a-zA-Z0-9:-]+)(\s*=\s*)(".*?"|'.*?'|[^\s>]+)/g, function(m, attr, eq, val) {
              return '<span class="token attr-name">' + escapeHtml(attr) + '</span>' + eq + '<span class="token attr-value">' + escapeHtml(val) + '</span>';
            });
            result += '&lt;' + (isClose ? '/' : '') + '<span class="token tag">' + tagName + '</span>' + restHighlighted + '&gt;';
          } else if (/^\d/.test(text)) {
            result += '<span class="token number">' + escapeHtml(text) + '</span>';
          } else if (new RegExp('^(?:' + kwList + ')$', l === 'sql' ? 'i' : '').test(text)) {
            result += '<span class="token keyword">' + escapeHtml(text) + '</span>';
          } else if (/^[A-Z]/.test(text)) {
            result += '<span class="token class-name">' + escapeHtml(text) + '</span>';
          } else if (code[match.index + text.length] === '(' || /^\s*\(/.test(code.slice(match.index + text.length))) {
            result += '<span class="token function">' + escapeHtml(text) + '</span>';
          } else if (/^[{}()[\];,]$/.test(text)) {
            result += '<span class="token punctuation">' + escapeHtml(text) + '</span>';
          } else {
            result += escapeHtml(text);
          }

          lastIndex = masterRegex.lastIndex;
        }

        if (lastIndex < code.length) {
          result += escapeHtml(code.slice(lastIndex));
        }

        return result;
      }

      for (var c = 0; c < postContainers.length; c++) {
        var container = postContainers[c];
        var preElements = container.querySelectorAll('pre');

        for (var i = 0; i < preElements.length; i++) {
          var pre = preElements[i];

          if (pre.getAttribute('data-vtj-code') === 'true' || pre.closest('.vtj-code-block')) {
            continue;
          }

          var codeChild = pre.querySelector('code');
          var langName = detectLanguage(pre, codeChild);

          // Get raw text
          var rawText = (codeChild ? codeChild.textContent : pre.textContent);

          // Clean any Blogger gadget artifacts
          rawText = rawText.replace(/^(?:HTML|CSS|JavaScript|Java|Python|Bash|SQL)\s+ExpandCopy\s+/i, '');
          rawText = rawText.replace(/^ExpandCopy\s+/i, '');

          // Container
          var blockWrapper = document.createElement('div');
          blockWrapper.className = 'vtj-code-block';
          blockWrapper.setAttribute('data-lang', langName.toLowerCase());

          // Header
          var header = document.createElement('div');
          header.className = 'vtj-code-header';

          var headerLeft = document.createElement('div');
          headerLeft.className = 'vtj-code-header-left';

          var dotsDiv = document.createElement('div');
          dotsDiv.className = 'vtj-code-dots';
          dotsDiv.innerHTML = '<span class="vtj-code-dot vtj-code-dot-red"></span>' +
                              '<span class="vtj-code-dot vtj-code-dot-yellow"></span>' +
                              '<span class="vtj-code-dot vtj-code-dot-green"></span>';

          var langSpan = document.createElement('span');
          langSpan.className = 'vtj-code-lang';
          langSpan.textContent = langName;

          headerLeft.appendChild(dotsDiv);
          headerLeft.appendChild(langSpan);

          // Copy button
          var copyBtn = document.createElement('button');
          copyBtn.type = 'button';
          copyBtn.className = 'vtj-code-copy-btn';
          copyBtn.setAttribute('aria-label', 'Copy code to clipboard');
          copyBtn.innerHTML = copyIconSvg + '<span class="vtj-copy-label">Copy</span>';

          header.appendChild(headerLeft);
          header.appendChild(copyBtn);

          // Code area wrapper (Condition 1 & 2)
          var codeWrapper = document.createElement('div');
          codeWrapper.className = 'vtj-code-wrapper';

          // Syntax Highlighting (Condition 3)
          var highlightedHtml = highlightCode(rawText, langName);

          var newPre = document.createElement('pre');
          var newCode = document.createElement('code');
          newCode.className = 'language-' + langName.toLowerCase();
          newCode.innerHTML = highlightedHtml;
          newPre.appendChild(newCode);

          codeWrapper.appendChild(newPre);
          blockWrapper.appendChild(header);
          blockWrapper.appendChild(codeWrapper);

          // Replace old pre with styled block
          pre.parentNode.insertBefore(blockWrapper, pre);
          pre.parentNode.removeChild(pre);

          // Copy functionality
          (function (textToCopy, btn) {
            btn.addEventListener('click', function () {
              function onSuccess() {
                btn.classList.add('is-copied');
                btn.innerHTML = checkIconSvg + '<span class="vtj-copy-label">Copied!</span>';
                setTimeout(function () {
                  btn.classList.remove('is-copied');
                  btn.innerHTML = copyIconSvg + '<span class="vtj-copy-label">Copy</span>';
                }, 2000);
              }

              if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(textToCopy).then(onSuccess).catch(function () {
                  fallbackCopy(textToCopy, onSuccess);
                });
              } else {
                fallbackCopy(textToCopy, onSuccess);
              }
            });
          })(rawText, copyBtn);

          function fallbackCopy(text, cb) {
            var ta = document.createElement('textarea');
            ta.value = text;
            ta.style.position = 'fixed';
            ta.style.left = '-9999px';
            ta.style.top = '0';
            document.body.appendChild(ta);
            ta.focus();
            ta.select();
            try {
              document.execCommand('copy');
              cb();
            } catch (err) {
              console.error('Copy failed:', err);
            }
            document.body.removeChild(ta);
          }
        }
      }
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', initCodeBlocks);
    } else {
      initCodeBlocks();
    }

    /* ---- Mobile Footer Accordion ---- */
    var footerCols = document.querySelectorAll('.site-footer .vtj-footer-col:not(.vtj-col-brand)');
    footerCols.forEach(function (col) {
      var heading = col.querySelector('.vtj-footer-heading');
      if (heading) {
        heading.addEventListener('click', function () {
          if (window.innerWidth <= 767) {
            col.classList.toggle('is-open');
          }
        });
      }
    });

    /* ---- Back to Top Smooth Scroll ---- */
    var bttBtn = document.getElementById('vtj-btt-btn');
    if (bttBtn) {
      bttBtn.addEventListener('click', function (e) {
        e.preventDefault();
        window.scrollTo({ top: 0, behavior: 'smooth' });
      });
    }
  })();
  //
